    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    parent_location_id TEXT CHECK (parent_location_id IS NULL OR (length(parent_location_id) = 36 AND parent_location_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL DEFAULT 'site' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('site', 'building', 'area', 'yard', 'transit', 'postal'))),
    code TEXT CHECK (code IS NULL OR (length(code) BETWEEN 1 AND 40)),
    name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
    address_line1 TEXT,
    address_line2 TEXT,
    locality TEXT,
    region TEXT,
    postal_code TEXT,
    country_code TEXT CHECK (country_code IS NULL OR (length(country_code) = 2 AND country_code NOT GLOB '*[^A-Z]*')),
    latitude TEXT CHECK (latitude IS NULL OR (latitude NOT GLOB '*[^0-9.-]*' AND length(latitude) BETWEEN 1 AND 40)),
    longitude TEXT CHECK (longitude IS NULL OR (longitude NOT GLOB '*[^0-9.-]*' AND length(longitude) BETWEEN 1 AND 40)),
    coordinate_source TEXT CHECK (coordinate_source IS NULL OR ((length(coordinate_source) BETWEEN 1 AND 63 AND coordinate_source GLOB '[a-z]*' AND coordinate_source NOT GLOB '*[^a-z0-9_]*') AND (coordinate_source IN ('manual', 'device', 'geocoded', 'import')))),
    timezone TEXT CHECK (timezone IS NULL OR (length(timezone) BETWEEN 1 AND 64)),
    is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (parent_location_id IS NULL OR parent_location_id <> id),
    CHECK ((latitude IS NULL) = (longitude IS NULL)),
    CHECK (latitude IS NULL OR (CAST(latitude AS REAL) BETWEEN -90 AND 90 AND CAST(longitude AS REAL) BETWEEN -180 AND 180)),
    CHECK ((coordinate_source IS NULL) = (latitude IS NULL)),
    CHECK (kind <> 'transit' OR (address_line1 IS NULL AND address_line2 IS NULL AND postal_code IS NULL)),
    FOREIGN KEY (parent_location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
