    contact_id TEXT CHECK (contact_id IS NULL OR (length(contact_id) = 36 AND contact_id NOT GLOB '*[^0-9a-f-]*')),
    contact_note TEXT,
    is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
    PRIMARY KEY (id),
    FOREIGN KEY (party_id, contact_id) REFERENCES party_contacts (party_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (party_id) REFERENCES parties (id) ON DELETE CASCADE,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_party_locations__party_id_location_id_id ON party_locations (party_id, location_id, id);
CREATE INDEX IF NOT EXISTS ix_party_locations__party_id ON party_locations (party_id);
CREATE INDEX IF NOT EXISTS ix_party_locations__location_id ON party_locations (location_id);

-- customer_groups <- masters.customer_groups
CREATE TABLE IF NOT EXISTS customer_groups (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
    description TEXT,
    PRIMARY KEY (id)
) STRICT;

-- customer_profiles <- masters.customer_profiles
CREATE TABLE IF NOT EXISTS customer_profiles (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    party_id TEXT NOT NULL CHECK (length(party_id) = 36 AND party_id NOT GLOB '*[^0-9a-f-]*'),
    status TEXT NOT NULL DEFAULT 'active' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('active', 'on_hold', 'blocked', 'cash_only'))),
    status_reason TEXT,
    status_changed_by TEXT CHECK (status_changed_by IS NULL OR (length(status_changed_by) = 36 AND status_changed_by NOT GLOB '*[^0-9a-f-]*')),
    status_changed_at INTEGER,
    status_source TEXT,
    credit_limit_minor INTEGER CHECK (credit_limit_minor IS NULL OR (credit_limit_minor >= 0)),
    currency_code TEXT CHECK (currency_code IS NULL OR (length(currency_code) = 3 AND currency_code NOT GLOB '*[^A-Z]*')),
    payment_terms_days INTEGER CHECK (payment_terms_days IS NULL OR (payment_terms_days BETWEEN 0 AND 365)),
    po_required INTEGER NOT NULL DEFAULT 0 CHECK (po_required IN (0, 1)),
    do_not_rent INTEGER NOT NULL DEFAULT 0 CHECK (do_not_rent IN (0, 1)),
    do_not_rent_reason TEXT,
    risk_notes TEXT,
    is_tax_exempt INTEGER NOT NULL DEFAULT 0 CHECK (is_tax_exempt IN (0, 1)),
    exemption_reason TEXT,
    is_reverse_charge INTEGER NOT NULL DEFAULT 0 CHECK (is_reverse_charge IN (0, 1)),
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    locale TEXT CHECK (locale IS NULL OR (length(locale) BETWEEN 2 AND 35)),
    customer_group_id TEXT CHECK (customer_group_id IS NULL OR (length(customer_group_id) = 36 AND customer_group_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (party_id),
    CHECK (do_not_rent OR do_not_rent_reason IS NULL),
    CHECK (is_tax_exempt OR exemption_reason IS NULL),
    FOREIGN KEY (party_id) REFERENCES parties (id) ON DELETE CASCADE,
    FOREIGN KEY (customer_group_id) REFERENCES customer_groups (id) ON DELETE SET NULL
) STRICT;

-- supplier_profiles <- masters.supplier_profiles
CREATE TABLE IF NOT EXISTS supplier_profiles (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    party_id TEXT NOT NULL CHECK (length(party_id) = 36 AND party_id NOT GLOB '*[^0-9a-f-]*'),
    supplier_code TEXT CHECK (supplier_code IS NULL OR (length(supplier_code) BETWEEN 1 AND 40)),
    account_number TEXT,
    payment_terms TEXT,
    currency_code TEXT CHECK (currency_code IS NULL OR (length(currency_code) = 3 AND currency_code NOT GLOB '*[^A-Z]*')),
    lead_time_days INTEGER CHECK (lead_time_days IS NULL OR (lead_time_days >= 0)),
    is_preferred INTEGER NOT NULL DEFAULT 0 CHECK (is_preferred IN (0, 1)),
    rating INTEGER CHECK (rating IS NULL OR (rating BETWEEN 1 AND 5)),
    PRIMARY KEY (party_id),
    FOREIGN KEY (party_id) REFERENCES parties (id) ON DELETE CASCADE
) STRICT;

-- owner_profiles <- masters.owner_profiles
CREATE TABLE IF NOT EXISTS owner_profiles (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    party_id TEXT NOT NULL CHECK (length(party_id) = 36 AND party_id NOT GLOB '*[^0-9a-f-]*'),
    billback_enabled INTEGER NOT NULL DEFAULT 0 CHECK (billback_enabled IN (0, 1)),
    activity_visibility TEXT NOT NULL DEFAULT 'summary' CHECK ((length(activity_visibility) BETWEEN 1 AND 63 AND activity_visibility GLOB '[a-z]*' AND activity_visibility NOT GLOB '*[^a-z0-9_]*') AND (activity_visibility IN ('none', 'summary', 'full'))),
    statement_email_point_id TEXT CHECK (statement_email_point_id IS NULL OR (length(statement_email_point_id) = 36 AND statement_email_point_id NOT GLOB '*[^0-9a-f-]*')),
    notes TEXT,
    PRIMARY KEY (party_id),
    FOREIGN KEY (party_id, statement_email_point_id) REFERENCES party_contact_points (party_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (party_id) REFERENCES parties (id) ON DELETE CASCADE
) STRICT;

-- asset_owner_assignments <- masters.asset_owner_assignments
CREATE TABLE IF NOT EXISTS asset_owner_assignments (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    owner_party_id TEXT NOT NULL CHECK (length(owner_party_id) = 36 AND owner_party_id NOT GLOB '*[^0-9a-f-]*'),
    ownership_kind TEXT NOT NULL DEFAULT 'economic' CHECK ((length(ownership_kind) BETWEEN 1 AND 63 AND ownership_kind GLOB '[a-z]*' AND ownership_kind NOT GLOB '*[^a-z0-9_]*') AND (ownership_kind IN ('economic', 'legal'))),
    share_bp INTEGER NOT NULL CHECK (share_bp BETWEEN 1 AND 10000),
    valid_during_start TEXT NOT NULL CHECK (valid_during_start GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    valid_during_end TEXT CHECK (valid_during_end IS NULL OR (valid_during_end GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    reason TEXT,
    predecessor_assignment_id TEXT CHECK (predecessor_assignment_id IS NULL OR (length(predecessor_assignment_id) = 36 AND predecessor_assignment_id NOT GLOB '*[^0-9a-f-]*')),
    recorded_by TEXT CHECK (recorded_by IS NULL OR (length(recorded_by) = 36 AND recorded_by NOT GLOB '*[^0-9a-f-]*')),
    recorded_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    CHECK (valid_during_start IS NOT NULL AND (valid_during_end IS NULL OR valid_during_end > valid_during_start)),
    CHECK (predecessor_assignment_id IS NULL OR predecessor_assignment_id <> id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (predecessor_assignment_id) REFERENCES asset_owner_assignments (id) ON DELETE SET NULL
) STRICT;
CREATE INDEX IF NOT EXISTS ix_asset_owner_assignments__asset_id ON asset_owner_assignments (asset_id);
CREATE INDEX IF NOT EXISTS ix_asset_owner_assignments__owner_party_id ON asset_owner_assignments (owner_party_id);

-- ================================================= area stock

-- products <- stock.products
CREATE TABLE IF NOT EXISTS products (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    sku TEXT NOT NULL CHECK (length(sku) BETWEEN 1 AND 100),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 300),
    category_id TEXT CHECK (category_id IS NULL OR (length(category_id) = 36 AND category_id NOT GLOB '*[^0-9a-f-]*')),
    uom_code TEXT NOT NULL DEFAULT 'ea' CHECK (length(uom_code) BETWEEN 1 AND 20),
    tracking_mode TEXT NOT NULL DEFAULT 'none' CHECK ((length(tracking_mode) BETWEEN 1 AND 63 AND tracking_mode GLOB '[a-z]*' AND tracking_mode NOT GLOB '*[^a-z0-9_]*') AND (tracking_mode IN ('none', 'lot', 'serial'))),
    manufacturer_name TEXT,
    model_number TEXT,
    revision TEXT,
    gtin TEXT CHECK (gtin IS NULL OR (length(gtin) IN (8, 12, 13, 14) AND gtin NOT GLOB '*[^0-9]*')),
    origin_country_code TEXT CHECK (origin_country_code IS NULL OR (length(origin_country_code) = 2 AND origin_country_code NOT GLOB '*[^A-Z]*')),
    standard_unit_cost TEXT CHECK (standard_unit_cost IS NULL OR ((standard_unit_cost NOT GLOB '*[^0-9.-]*' AND length(standard_unit_cost) BETWEEN 1 AND 40) AND (standard_unit_cost >= 0))),
    standard_cost_currency TEXT CHECK (standard_cost_currency IS NULL OR (length(standard_cost_currency) = 3 AND standard_cost_currency NOT GLOB '*[^A-Z]*')),
    default_reorder_qty_micros INTEGER CHECK (default_reorder_qty_micros IS NULL OR (default_reorder_qty_micros > 0)),
    abc_class TEXT CHECK (abc_class IS NULL OR (abc_class IN ('A', 'B', 'C'))),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK ((standard_unit_cost IS NULL) = (standard_cost_currency IS NULL)),
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE SET NULL
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_products__sku ON products (sku);

-- product_rental_profiles <- stock.product_rental_profiles
CREATE TABLE IF NOT EXISTS product_rental_profiles (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    rental_kind TEXT NOT NULL DEFAULT 'sale' CHECK ((length(rental_kind) BETWEEN 1 AND 63 AND rental_kind GLOB '[a-z]*' AND rental_kind NOT GLOB '*[^a-z0-9_]*') AND (rental_kind IN ('sale', 'consumable', 'accessory', 'bulk_rental'))),
    is_public INTEGER NOT NULL DEFAULT 0 CHECK (is_public IN (0, 1)),
    taxable INTEGER NOT NULL DEFAULT 1 CHECK (taxable IN (0, 1)),
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    replacement_minor INTEGER CHECK (replacement_minor IS NULL OR (replacement_minor >= 0)),
    damage_fee_minor INTEGER CHECK (damage_fee_minor IS NULL OR (damage_fee_minor >= 0)),
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    PRIMARY KEY (product_id),
    CHECK (currency IS NOT NULL OR (replacement_minor IS NULL AND damage_fee_minor IS NULL)),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
) STRICT;

-- product_suppliers <- stock.product_suppliers
CREATE TABLE IF NOT EXISTS product_suppliers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    supplier_party_id TEXT NOT NULL CHECK (length(supplier_party_id) = 36 AND supplier_party_id NOT GLOB '*[^0-9a-f-]*'),
    supplier_sku TEXT,
    supplier_description TEXT,
    unit_cost TEXT CHECK (unit_cost IS NULL OR ((unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40) AND (unit_cost >= 0))),
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    min_order_qty_micros INTEGER CHECK (min_order_qty_micros IS NULL OR (min_order_qty_micros > 0)),
    pack_size_qty_micros INTEGER CHECK (pack_size_qty_micros IS NULL OR (pack_size_qty_micros > 0)),
    lead_time_days INTEGER CHECK (lead_time_days IS NULL OR (lead_time_days >= 0)),
    price_checked_at INTEGER,
    is_preferred INTEGER NOT NULL DEFAULT 0 CHECK (is_preferred IN (0, 1)),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK ((unit_cost IS NULL) = (currency IS NULL)),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE,
    FOREIGN KEY (supplier_party_id) REFERENCES parties (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_product_suppliers__product_id ON product_suppliers (product_id) WHERE is_preferred = 1 AND archived_at IS NULL;

-- product_lots <- stock.product_lots
CREATE TABLE IF NOT EXISTS product_lots (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    lot_code TEXT NOT NULL CHECK (length(lot_code) BETWEEN 1 AND 100),
    produced_on TEXT CHECK (produced_on IS NULL OR (produced_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    expires_on TEXT CHECK (expires_on IS NULL OR (expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (expires_on >= produced_on),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_product_lots__product_id_lot_code ON product_lots (product_id, lot_code);
CREATE UNIQUE INDEX IF NOT EXISTS ux_product_lots__product_id_id ON product_lots (product_id, id);

-- stock_units <- stock.stock_units
CREATE TABLE IF NOT EXISTS stock_units (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    lot_id TEXT CHECK (lot_id IS NULL OR (length(lot_id) = 36 AND lot_id NOT GLOB '*[^0-9a-f-]*')),
    serial_number TEXT NOT NULL CHECK (length(serial_number) BETWEEN 1 AND 200),
    status TEXT NOT NULL DEFAULT 'in_stock' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('in_stock', 'issued', 'installed', 'scrapped', 'returned_to_supplier'))),
    installed_asset_id TEXT CHECK (installed_asset_id IS NULL OR (length(installed_asset_id) = 36 AND installed_asset_id NOT GLOB '*[^0-9a-f-]*')),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK ((status = 'installed') = (installed_asset_id IS NOT NULL)),
    FOREIGN KEY (product_id, lot_id) REFERENCES product_lots (product_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (installed_asset_id) REFERENCES assets (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_units__product_id_serial_number ON stock_units (product_id, serial_number);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_units__product_id_id ON stock_units (product_id, id);

-- asset_product_links <- stock.asset_product_links
CREATE TABLE IF NOT EXISTS asset_product_links (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    quantity_micros INTEGER NOT NULL CHECK (quantity_micros > 0),
    serial_number TEXT,
    lot_code TEXT,
    notes TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;

-- asset_taxonomy_categories <- masters.asset_taxonomy_categories
CREATE TABLE IF NOT EXISTS asset_taxonomy_categories (
    created_at INTEGER NOT NULL,
    id TEXT NOT NULL CHECK (length(id) BETWEEN 1 AND 63),
    taxonomy_version INTEGER NOT NULL CHECK (taxonomy_version >= 1),
    label TEXT NOT NULL CHECK (json_valid(label) AND json_type(label) = 'object'),
    legacy_marketplace_category TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
) STRICT;

-- asset_taxonomy_subcategories <- masters.asset_taxonomy_subcategories
CREATE TABLE IF NOT EXISTS asset_taxonomy_subcategories (
    created_at INTEGER NOT NULL,
    id TEXT NOT NULL CHECK (instr(id, '.') > 1),
    category_id TEXT NOT NULL,
    label TEXT NOT NULL CHECK (json_valid(label) AND json_type(label) = 'object'),
    aliases TEXT CHECK (aliases IS NULL OR (json_valid(aliases) AND json_type(aliases) = 'array')),
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CHECK (substr(id, 1, length(category_id) + 1) = category_id || '.'),
    FOREIGN KEY (category_id) REFERENCES asset_taxonomy_categories (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_taxonomy_subcategories__category_id_id ON asset_taxonomy_subcategories (category_id, id);

-- bins <- stock.bins
CREATE TABLE IF NOT EXISTS bins (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    archived_at INTEGER,
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    code TEXT NOT NULL CHECK (length(code) BETWEEN 1 AND 64),
    name TEXT,
    barcode TEXT,
    bin_kind TEXT,
    capacity_qty_micros INTEGER CHECK (capacity_qty_micros IS NULL OR (capacity_qty_micros > 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_bins__location_id_id ON bins (location_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_bins__location_id_code ON bins (location_id, code);

-- stock_positions <- stock.stock_positions
CREATE TABLE IF NOT EXISTS stock_positions (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    bin_id TEXT CHECK (bin_id IS NULL OR (length(bin_id) = 36 AND bin_id NOT GLOB '*[^0-9a-f-]*')),
    lot_id TEXT CHECK (lot_id IS NULL OR (length(lot_id) = 36 AND lot_id NOT GLOB '*[^0-9a-f-]*')),
    stock_unit_id TEXT CHECK (stock_unit_id IS NULL OR (length(stock_unit_id) = 36 AND stock_unit_id NOT GLOB '*[^0-9a-f-]*')),
    condition_code TEXT NOT NULL DEFAULT 'good' CHECK ((length(condition_code) BETWEEN 1 AND 63 AND condition_code GLOB '[a-z]*' AND condition_code NOT GLOB '*[^a-z0-9_]*') AND (condition_code IN ('good', 'damaged', 'quarantine', 'in_repair'))),
    on_hand_qty_micros INTEGER NOT NULL CHECK (on_hand_qty_micros >= 0),
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    CHECK (stock_unit_id IS NULL OR on_hand_qty_micros IN (0, 1000000)),
    FOREIGN KEY (location_id, bin_id) REFERENCES bins (location_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id, lot_id) REFERENCES product_lots (product_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id, stock_unit_id) REFERENCES stock_units (product_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_positions__product_id_location_id_bin_id_lot__4ad52927 ON stock_positions (product_id, location_id, (bin_id IS NULL), COALESCE(bin_id, ''), (lot_id IS NULL), COALESCE(lot_id, ''), (stock_unit_id IS NULL), COALESCE(stock_unit_id, ''), condition_code);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_positions__id_product_id ON stock_positions (id, product_id);

-- stock_movements <- stock.stock_movements
CREATE TABLE IF NOT EXISTS stock_movements (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('receipt', 'issue', 'return', 'transfer', 'transfer_dispatch', 'transfer_receipt', 'adjustment', 'count', 'opening_balance'))),
    status TEXT NOT NULL DEFAULT 'draft' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'requested', 'approved', 'declined', 'posted', 'cancelled'))),
    number TEXT,
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    to_location_id TEXT CHECK (to_location_id IS NULL OR (length(to_location_id) = 36 AND to_location_id NOT GLOB '*[^0-9a-f-]*')),
    effective_at INTEGER,
    posted_at INTEGER,
    posted_by TEXT CHECK (posted_by IS NULL OR (length(posted_by) = 36 AND posted_by NOT GLOB '*[^0-9a-f-]*')),
    requested_by TEXT CHECK (requested_by IS NULL OR (length(requested_by) = 36 AND requested_by NOT GLOB '*[^0-9a-f-]*')),
    approved_by TEXT CHECK (approved_by IS NULL OR (length(approved_by) = 36 AND approved_by NOT GLOB '*[^0-9a-f-]*')),
    approved_at INTEGER,
    decision_note TEXT,
    purchase_order_id TEXT CHECK (purchase_order_id IS NULL OR (length(purchase_order_id) = 36 AND purchase_order_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    issued_to_user_id TEXT CHECK (issued_to_user_id IS NULL OR (length(issued_to_user_id) = 36 AND issued_to_user_id NOT GLOB '*[^0-9a-f-]*')),
    source_movement_id TEXT CHECK (source_movement_id IS NULL OR (length(source_movement_id) = 36 AND source_movement_id NOT GLOB '*[^0-9a-f-]*')),
    reverses_movement_id TEXT CHECK (reverses_movement_id IS NULL OR (length(reverses_movement_id) = 36 AND reverses_movement_id NOT GLOB '*[^0-9a-f-]*')),
    count_scope TEXT CHECK (count_scope IS NULL OR ((length(count_scope) BETWEEN 1 AND 63 AND count_scope GLOB '[a-z]*' AND count_scope NOT GLOB '*[^a-z0-9_]*') AND (count_scope IN ('full', 'category', 'bin', 'part_list', 'abc_a', 'abc_b', 'abc_c')))),
    blind_count INTEGER NOT NULL DEFAULT 0 CHECK (blind_count IN (0, 1)),
    counted_by TEXT CHECK (counted_by IS NULL OR (length(counted_by) = 36 AND counted_by NOT GLOB '*[^0-9a-f-]*')),
    started_at INTEGER,
    completed_at INTEGER,
    scheduled_on TEXT CHECK (scheduled_on IS NULL OR (scheduled_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    carrier TEXT,
    tracking_number TEXT,
    packing_slip_no TEXT,
    reference_text TEXT,
    external_reference TEXT,
    command_id TEXT CHECK (command_id IS NULL OR (length(command_id) = 36 AND command_id NOT GLOB '*[^0-9a-f-]*')),
    source_key TEXT,
    notes TEXT,
    PRIMARY KEY (id),
    CHECK ((kind IN ('transfer', 'transfer_dispatch', 'transfer_receipt')) = (to_location_id IS NOT NULL) AND (to_location_id IS NULL OR to_location_id <> location_id)),
    CHECK ((kind = 'count') = (count_scope IS NOT NULL)),
    CHECK (status <> 'posted' OR (number IS NOT NULL AND posted_at IS NOT NULL AND effective_at IS NOT NULL)),
    CHECK (source_movement_id IS NULL OR kind = 'transfer_receipt'),
    CHECK (reverses_movement_id IS NULL OR reverses_movement_id <> id),
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (to_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (source_movement_id) REFERENCES stock_movements (id) ON DELETE RESTRICT,
    FOREIGN KEY (reverses_movement_id) REFERENCES stock_movements (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movements__kind_number ON stock_movements (kind, number);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movements__command_id ON stock_movements (command_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movements__source_key ON stock_movements (source_key);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movements__reverses_movement_id ON stock_movements (reverses_movement_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movements__id_purchase_order_id ON stock_movements (id, purchase_order_id);

-- stock_movement_lines <- stock.stock_movement_lines
CREATE TABLE IF NOT EXISTS stock_movement_lines (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    movement_id TEXT NOT NULL CHECK (length(movement_id) = 36 AND movement_id NOT GLOB '*[^0-9a-f-]*'),
    line_no INTEGER NOT NULL CHECK (line_no >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    uom_code TEXT,
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    bin_id TEXT CHECK (bin_id IS NULL OR (length(bin_id) = 36 AND bin_id NOT GLOB '*[^0-9a-f-]*')),
    to_bin_id TEXT CHECK (to_bin_id IS NULL OR (length(to_bin_id) = 36 AND to_bin_id NOT GLOB '*[^0-9a-f-]*')),
    lot_id TEXT CHECK (lot_id IS NULL OR (length(lot_id) = 36 AND lot_id NOT GLOB '*[^0-9a-f-]*')),
    stock_unit_id TEXT CHECK (stock_unit_id IS NULL OR (length(stock_unit_id) = 36 AND stock_unit_id NOT GLOB '*[^0-9a-f-]*')),
    condition_code TEXT NOT NULL DEFAULT 'good' CHECK ((length(condition_code) BETWEEN 1 AND 63 AND condition_code GLOB '[a-z]*' AND condition_code NOT GLOB '*[^a-z0-9_]*') AND (condition_code IN ('good', 'damaged', 'quarantine', 'in_repair'))),
    requested_qty_micros INTEGER CHECK (requested_qty_micros IS NULL OR (requested_qty_micros > 0)),
    quantity_micros INTEGER,
    expected_qty_micros INTEGER,
    counted_qty_micros INTEGER CHECK (counted_qty_micros IS NULL OR (counted_qty_micros >= 0)),
    observed_position_id TEXT CHECK (observed_position_id IS NULL OR (length(observed_position_id) = 36 AND observed_position_id NOT GLOB '*[^0-9a-f-]*')),
    observed_position_version INTEGER,
    counted_at INTEGER,
    counted_by TEXT CHECK (counted_by IS NULL OR (length(counted_by) = 36 AND counted_by NOT GLOB '*[^0-9a-f-]*')),
    recount_required INTEGER NOT NULL DEFAULT 0 CHECK (recount_required IN (0, 1)),
    purchase_order_id TEXT CHECK (purchase_order_id IS NULL OR (length(purchase_order_id) = 36 AND purchase_order_id NOT GLOB '*[^0-9a-f-]*')),
    purchase_order_line_id TEXT CHECK (purchase_order_line_id IS NULL OR (length(purchase_order_line_id) = 36 AND purchase_order_line_id NOT GLOB '*[^0-9a-f-]*')),
    dispatch_line_id TEXT CHECK (dispatch_line_id IS NULL OR (length(dispatch_line_id) = 36 AND dispatch_line_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_material_id TEXT CHECK (work_order_material_id IS NULL OR (length(work_order_material_id) = 36 AND work_order_material_id NOT GLOB '*[^0-9a-f-]*')),
    activity_cost_line_id TEXT CHECK (activity_cost_line_id IS NULL OR (length(activity_cost_line_id) = 36 AND activity_cost_line_id NOT GLOB '*[^0-9a-f-]*')),
    discrepancy_qty_micros INTEGER,
    discrepancy_reason TEXT,
    reason_code TEXT,
    unit_cost TEXT CHECK (unit_cost IS NULL OR ((unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40) AND (unit_cost >= 0))),
    cost_currency TEXT CHECK (cost_currency IS NULL OR (length(cost_currency) = 3 AND cost_currency NOT GLOB '*[^A-Z]*')),
    exchange_rate TEXT CHECK (exchange_rate IS NULL OR ((exchange_rate NOT GLOB '*[^0-9.-]*' AND length(exchange_rate) BETWEEN 1 AND 40) AND (exchange_rate > 0))),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (bin_id IS NULL OR location_id IS NOT NULL),
    CHECK (purchase_order_line_id IS NULL OR purchase_order_id IS NOT NULL),
    CHECK ((unit_cost IS NULL) = (cost_currency IS NULL)),
    FOREIGN KEY (movement_id, purchase_order_id) REFERENCES stock_movements (id, purchase_order_id) ON DELETE RESTRICT,
    FOREIGN KEY (purchase_order_id, purchase_order_line_id) REFERENCES purchase_order_lines (purchase_order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id, bin_id) REFERENCES bins (location_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id, lot_id) REFERENCES product_lots (product_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id, stock_unit_id) REFERENCES stock_units (product_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (movement_id) REFERENCES stock_movements (id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (to_bin_id) REFERENCES bins (id) ON DELETE RESTRICT,
    FOREIGN KEY (observed_position_id) REFERENCES stock_positions (id) ON DELETE RESTRICT,
    FOREIGN KEY (dispatch_line_id) REFERENCES stock_movement_lines (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_material_id) REFERENCES work_order_materials (id) ON DELETE RESTRICT,
    FOREIGN KEY (activity_cost_line_id) REFERENCES activity_cost_lines (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movement_lines__movement_id_line_no ON stock_movement_lines (movement_id, line_no);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_movement_lines__movement_id_id_product_id ON stock_movement_lines (movement_id, id, product_id);

-- stock_ledger_legs <- stock.stock_ledger_legs
CREATE TABLE IF NOT EXISTS stock_ledger_legs (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    movement_id TEXT NOT NULL CHECK (length(movement_id) = 36 AND movement_id NOT GLOB '*[^0-9a-f-]*'),
    line_id TEXT NOT NULL CHECK (length(line_id) = 36 AND line_id NOT GLOB '*[^0-9a-f-]*'),
    position_id TEXT NOT NULL CHECK (length(position_id) = 36 AND position_id NOT GLOB '*[^0-9a-f-]*'),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    qty_micros INTEGER NOT NULL CHECK (qty_micros <> 0),
    effective_at INTEGER NOT NULL,
    posted_at INTEGER NOT NULL,
    unit_cost TEXT CHECK (unit_cost IS NULL OR ((unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40) AND (unit_cost >= 0))),
    cost_currency TEXT CHECK (cost_currency IS NULL OR (length(cost_currency) = 3 AND cost_currency NOT GLOB '*[^A-Z]*')),
    cost_layer_id TEXT CHECK (cost_layer_id IS NULL OR (length(cost_layer_id) = 36 AND cost_layer_id NOT GLOB '*[^0-9a-f-]*')),
    reverses_leg_id TEXT CHECK (reverses_leg_id IS NULL OR (length(reverses_leg_id) = 36 AND reverses_leg_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK ((unit_cost IS NULL) = (cost_currency IS NULL)),
    FOREIGN KEY (movement_id, line_id, product_id) REFERENCES stock_movement_lines (movement_id, id, product_id) ON DELETE RESTRICT,
    FOREIGN KEY (position_id, product_id) REFERENCES stock_positions (id, product_id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (reverses_leg_id) REFERENCES stock_ledger_legs (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_ledger_legs__reverses_leg_id ON stock_ledger_legs (reverses_leg_id);

-- stock_reservations <- stock.stock_reservations
CREATE TABLE IF NOT EXISTS stock_reservations (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    position_id TEXT CHECK (position_id IS NULL OR (length(position_id) = 36 AND position_id NOT GLOB '*[^0-9a-f-]*')),
    quantity_micros INTEGER NOT NULL CHECK (quantity_micros > 0),
    state TEXT NOT NULL DEFAULT 'active' CHECK ((length(state) BETWEEN 1 AND 63 AND state GLOB '[a-z]*' AND state NOT GLOB '*[^a-z0-9_]*') AND (state IN ('active', 'consumed', 'released', 'expired'))),
    expires_at INTEGER,
    work_order_material_id TEXT CHECK (work_order_material_id IS NULL OR (length(work_order_material_id) = 36 AND work_order_material_id NOT GLOB '*[^0-9a-f-]*')),
    rental_order_line_id TEXT CHECK (rental_order_line_id IS NULL OR (length(rental_order_line_id) = 36 AND rental_order_line_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK ((work_order_material_id IS NOT NULL) + (rental_order_line_id IS NOT NULL) = 1),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (position_id) REFERENCES stock_positions (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_material_id) REFERENCES work_order_materials (id) ON DELETE RESTRICT,
    FOREIGN KEY (rental_order_line_id) REFERENCES rental_order_lines (id) ON DELETE RESTRICT
) STRICT;

-- stocking_policies <- stock.stocking_policies
CREATE TABLE IF NOT EXISTS stocking_policies (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    min_qty_micros INTEGER CHECK (min_qty_micros IS NULL OR (min_qty_micros >= 0)),
    max_qty_micros INTEGER CHECK (max_qty_micros IS NULL OR (max_qty_micros >= 0)),
    reorder_qty_micros INTEGER CHECK (reorder_qty_micros IS NULL OR (reorder_qty_micros > 0)),
    economic_order_qty_micros INTEGER CHECK (economic_order_qty_micros IS NULL OR (economic_order_qty_micros > 0)),
    safety_qty_micros INTEGER CHECK (safety_qty_micros IS NULL OR (safety_qty_micros >= 0)),
    consumption_window_days INTEGER CHECK (consumption_window_days IS NULL OR (consumption_window_days > 0)),
    last_reviewed_at INTEGER,
    PRIMARY KEY (id),
    CHECK (max_qty_micros >= min_qty_micros),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_stocking_policies__product_id_location_id ON stocking_policies (product_id, location_id);

-- work_order_materials <- stock.work_order_materials
CREATE TABLE IF NOT EXISTS work_order_materials (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    work_order_id TEXT NOT NULL CHECK (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*'),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    description TEXT,
    uom_code TEXT,
    required_qty_micros INTEGER NOT NULL CHECK (required_qty_micros > 0),
    planned_qty_micros INTEGER CHECK (planned_qty_micros IS NULL OR (planned_qty_micros >= 0)),
    issued_qty_micros INTEGER NOT NULL CHECK (issued_qty_micros >= 0),
    unit_cost TEXT CHECK (unit_cost IS NULL OR ((unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40) AND (unit_cost >= 0))),
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    PRIMARY KEY (id),
    CHECK (product_id IS NOT NULL OR description IS NOT NULL),
    CHECK ((unit_cost IS NULL) = (currency IS NULL)),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;

-- purchase_orders <- stock.purchase_orders (server-only check 'delete_only_draft_or_cancelled')
CREATE TABLE IF NOT EXISTS purchase_orders (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    number TEXT,
    supplier_party_id TEXT NOT NULL CHECK (length(supplier_party_id) = 36 AND supplier_party_id NOT GLOB '*[^0-9a-f-]*'),
    status TEXT NOT NULL DEFAULT 'draft' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'pending_approval', 'approved', 'ordered', 'partially_received', 'received', 'closed', 'cancelled'))),
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    subtotal_minor INTEGER NOT NULL DEFAULT 0,
    tax_total_minor INTEGER NOT NULL DEFAULT 0,
    shipping_minor INTEGER NOT NULL DEFAULT 0 CHECK (shipping_minor >= 0),
    discount_minor INTEGER NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
    grand_total_minor INTEGER NOT NULL DEFAULT 0,
    base_grand_total_minor INTEGER,
    exchange_rate TEXT CHECK (exchange_rate IS NULL OR ((exchange_rate NOT GLOB '*[^0-9.-]*' AND length(exchange_rate) BETWEEN 1 AND 40) AND (exchange_rate > 0))),
    expected_on TEXT CHECK (expected_on IS NULL OR (expected_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    ship_to_location_id TEXT CHECK (ship_to_location_id IS NULL OR (length(ship_to_location_id) = 36 AND ship_to_location_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    requested_by TEXT CHECK (requested_by IS NULL OR (length(requested_by) = 36 AND requested_by NOT GLOB '*[^0-9a-f-]*')),
    approved_by TEXT CHECK (approved_by IS NULL OR (length(approved_by) = 36 AND approved_by NOT GLOB '*[^0-9a-f-]*')),
    approved_at INTEGER,
    ordered_at INTEGER,
    closed_at INTEGER,
    notes TEXT,
    internal_notes TEXT,
    supplier_invoice_ref TEXT,
    qbo_bill_id TEXT,
    qbo_synced_at INTEGER,
    PRIMARY KEY (id),
    CHECK (grand_total_minor = subtotal_minor + tax_total_minor + shipping_minor - discount_minor),
    CHECK (status IN ('draft', 'pending_approval', 'cancelled') OR number IS NOT NULL),
    FOREIGN KEY (supplier_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (ship_to_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_purchase_orders__number ON purchase_orders (number);
CREATE UNIQUE INDEX IF NOT EXISTS ux_purchase_orders__id_currency ON purchase_orders (id, currency);

-- purchase_order_lines <- stock.purchase_order_lines
CREATE TABLE IF NOT EXISTS purchase_order_lines (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    purchase_order_id TEXT NOT NULL CHECK (length(purchase_order_id) = 36 AND purchase_order_id NOT GLOB '*[^0-9a-f-]*'),
    line_no INTEGER NOT NULL CHECK (line_no >= 1),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    description TEXT,
    supplier_sku TEXT,
    ordered_qty_micros INTEGER NOT NULL CHECK (ordered_qty_micros > 0),
    received_qty_micros INTEGER NOT NULL CHECK (received_qty_micros >= 0),
    unit_cost TEXT NOT NULL CHECK ((unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40) AND (unit_cost >= 0)),
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    tax_rate_pct TEXT CHECK (tax_rate_pct IS NULL OR ((tax_rate_pct NOT GLOB '*[^0-9.-]*' AND length(tax_rate_pct) BETWEEN 1 AND 40) AND (tax_rate_pct >= 0))),
    tax_minor INTEGER NOT NULL DEFAULT 0,
    line_total_minor INTEGER NOT NULL,
    deliver_to_location_id TEXT CHECK (deliver_to_location_id IS NULL OR (length(deliver_to_location_id) = 36 AND deliver_to_location_id NOT GLOB '*[^0-9a-f-]*')),
    deliver_to_bin_id TEXT CHECK (deliver_to_bin_id IS NULL OR (length(deliver_to_bin_id) = 36 AND deliver_to_bin_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (received_qty_micros <= ordered_qty_micros),
    CHECK (product_id IS NOT NULL OR description IS NOT NULL),
    CHECK (deliver_to_bin_id IS NULL OR deliver_to_location_id IS NOT NULL),
    FOREIGN KEY (purchase_order_id, currency) REFERENCES purchase_orders (id, currency) ON DELETE RESTRICT,
    FOREIGN KEY (deliver_to_location_id, deliver_to_bin_id) REFERENCES bins (location_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (deliver_to_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_purchase_order_lines__purchase_order_id_id ON purchase_order_lines (purchase_order_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_purchase_order_lines__purchase_order_id_line_no ON purchase_order_lines (purchase_order_id, line_no);

-- reorder_suggestions <- stock.reorder_suggestions
CREATE TABLE IF NOT EXISTS reorder_suggestions (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    on_hand_qty_micros INTEGER NOT NULL,
    min_qty_micros INTEGER,
    suggested_qty_micros INTEGER NOT NULL CHECK (suggested_qty_micros > 0),
    economic_order_qty_micros INTEGER,
    supplier_party_id TEXT CHECK (supplier_party_id IS NULL OR (length(supplier_party_id) = 36 AND supplier_party_id NOT GLOB '*[^0-9a-f-]*')),
    supplier_lead_time_days INTEGER,
    suggested_unit_cost TEXT CHECK (suggested_unit_cost IS NULL OR (suggested_unit_cost NOT GLOB '*[^0-9.-]*' AND length(suggested_unit_cost) BETWEEN 1 AND 40)),
    suggested_currency TEXT CHECK (suggested_currency IS NULL OR (length(suggested_currency) = 3 AND suggested_currency NOT GLOB '*[^A-Z]*')),
    consumption_rate_per_day_micros INTEGER,
    days_of_cover TEXT CHECK (days_of_cover IS NULL OR (days_of_cover NOT GLOB '*[^0-9.-]*' AND length(days_of_cover) BETWEEN 1 AND 40)),
    reason_code TEXT,
    generated_at INTEGER NOT NULL,
    expires_at INTEGER,
    PRIMARY KEY (id),
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (supplier_party_id) REFERENCES parties (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_reorder_suggestions__product_id_location_id ON reorder_suggestions (product_id, location_id);

-- label_templates <- stock.label_templates
CREATE TABLE IF NOT EXISTS label_templates (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    target TEXT NOT NULL CHECK ((length(target) BETWEEN 1 AND 63 AND target GLOB '[a-z]*' AND target NOT GLOB '*[^a-z0-9_]*') AND (target IN ('part', 'bin', 'asset', 'po'))),
    width_mm TEXT NOT NULL CHECK ((width_mm NOT GLOB '*[^0-9.-]*' AND length(width_mm) BETWEEN 1 AND 40) AND (width_mm > 0)),
    height_mm TEXT NOT NULL CHECK ((height_mm NOT GLOB '*[^0-9.-]*' AND length(height_mm) BETWEEN 1 AND 40) AND (height_mm > 0)),
    layout TEXT NOT NULL CHECK (json_valid(layout)),
    layout_version INTEGER NOT NULL DEFAULT 1 CHECK (layout_version >= 1),
    barcode_format TEXT,
    is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
    PRIMARY KEY (id)
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_label_templates__target ON label_templates (target) WHERE is_default = 1;

-- ================================================= area maint

-- assets <- masters.assets
CREATE TABLE IF NOT EXISTS assets (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 300),
    asset_type_code TEXT,
    account_asset_model_id TEXT CHECK (account_asset_model_id IS NULL OR (length(account_asset_model_id) = 36 AND account_asset_model_id NOT GLOB '*[^0-9a-f-]*')),
    make_override TEXT,
    model_override TEXT,
    model_year INTEGER CHECK (model_year IS NULL OR (model_year BETWEEN 1900 AND 2100)),
    serial_number TEXT,
    vin TEXT CHECK (vin IS NULL OR (vin = upper(trim(vin)) AND length(vin) BETWEEN 1 AND 32)),
    tags TEXT CHECK (tags IS NULL OR (json_valid(tags) AND json_type(tags) = 'array')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    parent_asset_id TEXT CHECK (parent_asset_id IS NULL OR (length(parent_asset_id) = 36 AND parent_asset_id NOT GLOB '*[^0-9a-f-]*')),
    status_code TEXT NOT NULL DEFAULT 'online' CHECK ((length(status_code) BETWEEN 1 AND 63 AND status_code GLOB '[a-z]*' AND status_code NOT GLOB '*[^a-z0-9_]*') AND (status_code IN ('online', 'offline', 'ignored', 'custom'))),
    status_since INTEGER NOT NULL,
    criticality_value_id TEXT CHECK (criticality_value_id IS NULL OR (length(criticality_value_id) = 36 AND criticality_value_id NOT GLOB '*[^0-9a-f-]*')),
    condition_score INTEGER CHECK (condition_score IS NULL OR (condition_score BETWEEN 0 AND 100)),
    criticality_ai_suggested TEXT CHECK (criticality_ai_suggested IS NULL OR (length(criticality_ai_suggested) = 36 AND criticality_ai_suggested NOT GLOB '*[^0-9a-f-]*')),
    criticality_ai_confidence TEXT CHECK (criticality_ai_confidence IS NULL OR ((criticality_ai_confidence NOT GLOB '*[^0-9.-]*' AND length(criticality_ai_confidence) BETWEEN 1 AND 40) AND (criticality_ai_confidence BETWEEN 0 AND 1))),
    rentable INTEGER NOT NULL DEFAULT 0 CHECK (rentable IN (0, 1)),
    rental_class_id TEXT CHECK (rental_class_id IS NULL OR (length(rental_class_id) = 36 AND rental_class_id NOT GLOB '*[^0-9a-f-]*')),
    rental_ownership TEXT CHECK (rental_ownership IS NULL OR ((length(rental_ownership) BETWEEN 1 AND 63 AND rental_ownership GLOB '[a-z]*' AND rental_ownership NOT GLOB '*[^a-z0-9_]*') AND (rental_ownership IN ('owned', 'subrented', 'sold')))),
    rental_sold_at INTEGER,
    global_uid TEXT NOT NULL CHECK (length(global_uid) = 36 AND global_uid NOT GLOB '*[^0-9a-f-]*'),
    taxonomy_category_id TEXT,
    taxonomy_subcategory_id TEXT,
    taxonomy_version INTEGER,
    classification_source TEXT CHECK (classification_source IS NULL OR ((length(classification_source) BETWEEN 1 AND 63 AND classification_source GLOB '[a-z]*' AND classification_source NOT GLOB '*[^a-z0-9_]*') AND (classification_source IN ('manual', 'qwen')))),
    avatar_color TEXT,
    avatar_initial TEXT CHECK (avatar_initial IS NULL OR (length(avatar_initial) <= 4)),
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    CHECK (parent_asset_id IS NULL OR parent_asset_id <> id),
    CHECK ((taxonomy_category_id IS NULL AND taxonomy_subcategory_id IS NULL AND taxonomy_version IS NULL AND classification_source IS NULL) OR (taxonomy_category_id IS NOT NULL AND taxonomy_version IS NOT NULL AND classification_source IS NOT NULL)),
    CHECK (rental_ownership IS DISTINCT FROM 'sold' OR rental_sold_at IS NOT NULL),
    FOREIGN KEY (taxonomy_category_id) REFERENCES asset_taxonomy_categories (id) ON DELETE RESTRICT,
    FOREIGN KEY (taxonomy_category_id, taxonomy_subcategory_id) REFERENCES asset_taxonomy_subcategories (category_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (account_asset_model_id) REFERENCES account_asset_models (id) ON DELETE SET NULL,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (parent_asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (criticality_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT,
    FOREIGN KEY (rental_class_id) REFERENCES rental_classes (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_assets__global_uid ON assets (global_uid);
CREATE UNIQUE INDEX IF NOT EXISTS ux_assets__id_location_id ON assets (id, location_id);

-- asset_status_intervals <- masters.asset_status_intervals
CREATE TABLE IF NOT EXISTS asset_status_intervals (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    status_code TEXT NOT NULL CHECK ((length(status_code) BETWEEN 1 AND 63 AND status_code GLOB '[a-z]*' AND status_code NOT GLOB '*[^a-z0-9_]*') AND (status_code IN ('online', 'offline', 'ignored', 'custom'))),
    custom_status_value_id TEXT CHECK (custom_status_value_id IS NULL OR (length(custom_status_value_id) = 36 AND custom_status_value_id NOT GLOB '*[^0-9a-f-]*')),
    downtime_type TEXT CHECK (downtime_type IS NULL OR ((length(downtime_type) BETWEEN 1 AND 63 AND downtime_type GLOB '[a-z]*' AND downtime_type NOT GLOB '*[^a-z0-9_]*') AND (downtime_type IN ('planned', 'unplanned')))),
    valid_during_start INTEGER NOT NULL,
    valid_during_end INTEGER,
    reason TEXT,
    actor_user_id TEXT CHECK (actor_user_id IS NULL OR (length(actor_user_id) = 36 AND actor_user_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK ((status_code = 'custom') = (custom_status_value_id IS NOT NULL)),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (custom_status_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_status_intervals__asset_id ON asset_status_intervals (asset_id);

-- asset_vehicle_details <- masters.asset_vehicle_details
CREATE TABLE IF NOT EXISTS asset_vehicle_details (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    body_class TEXT,
    fuel_type TEXT,
    gvwr TEXT,
    registration_number TEXT,
    registration_expires_on TEXT CHECK (registration_expires_on IS NULL OR (registration_expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    registration_file_id TEXT CHECK (registration_file_id IS NULL OR (length(registration_file_id) = 36 AND registration_file_id NOT GLOB '*[^0-9a-f-]*')),
    insurance_policy_number TEXT,
    insurance_expires_on TEXT CHECK (insurance_expires_on IS NULL OR (insurance_expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    insurance_file_id TEXT CHECK (insurance_file_id IS NULL OR (length(insurance_file_id) = 36 AND insurance_file_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (asset_id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (registration_file_id) REFERENCES files (id) ON DELETE RESTRICT,
    FOREIGN KEY (insurance_file_id) REFERENCES files (id) ON DELETE RESTRICT
