-- asset_tool_details <- masters.asset_tool_details
CREATE TABLE IF NOT EXISTS asset_tool_details (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    calibration_file_id TEXT CHECK (calibration_file_id IS NULL OR (length(calibration_file_id) = 36 AND calibration_file_id NOT GLOB '*[^0-9a-f-]*')),
    calibrated_on TEXT CHECK (calibrated_on IS NULL OR (calibrated_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    calibration_interval_days INTEGER CHECK (calibration_interval_days IS NULL OR (calibration_interval_days > 0)),
    calibration_due_on TEXT CHECK (calibration_due_on IS NULL OR (calibration_due_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    usage_unit TEXT,
    usage_value_micros INTEGER,
    replacement_value_minor INTEGER,
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    tracker_tag_id TEXT,
    tracker_kind TEXT,
    PRIMARY KEY (asset_id),
    CHECK (replacement_value_minor IS NULL OR currency IS NOT NULL),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (calibration_file_id) REFERENCES files (id) ON DELETE RESTRICT
) STRICT;

