-- asset_responsibilities <- masters.asset_responsibilities
CREATE TABLE IF NOT EXISTS asset_responsibilities (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    worker_id TEXT NOT NULL CHECK (length(worker_id) = 36 AND worker_id NOT GLOB '*[^0-9a-f-]*'),
    role TEXT NOT NULL DEFAULT 'responsible' CHECK (length(role) BETWEEN 1 AND 63 AND role GLOB '[a-z]*' AND role NOT GLOB '*[^a-z0-9_]*'),
    valid_on_start TEXT NOT NULL CHECK (valid_on_start GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    valid_on_end TEXT CHECK (valid_on_end IS NULL OR (valid_on_end GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    PRIMARY KEY (id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (worker_id) REFERENCES workers (id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_responsibilities__asset_id_worker_id_role ON asset_responsibilities (asset_id, worker_id, role);

-- categories <- masters.categories
CREATE TABLE IF NOT EXISTS categories (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    kind TEXT NOT NULL DEFAULT 'work_order' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('work_order', 'product', 'asset', 'request'))),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    parent_id TEXT CHECK (parent_id IS NULL OR (length(parent_id) = 36 AND parent_id NOT GLOB '*[^0-9a-f-]*')),
    default_priority TEXT CHECK (default_priority IS NULL OR ((length(default_priority) BETWEEN 1 AND 63 AND default_priority GLOB '[a-z]*' AND default_priority NOT GLOB '*[^a-z0-9_]*') AND (default_priority IN ('critical', 'high', 'medium', 'low')))),
    default_sla_hours INTEGER CHECK (default_sla_hours IS NULL OR (default_sla_hours > 0)),
    color TEXT,
    icon TEXT,
    system_code TEXT CHECK (system_code IS NULL OR (length(system_code) BETWEEN 1 AND 63 AND system_code GLOB '[a-z]*' AND system_code NOT GLOB '*[^a-z0-9_]*')),
    PRIMARY KEY (id),
    CHECK (parent_id IS NULL OR parent_id <> id),
    FOREIGN KEY (parent_id, kind) REFERENCES categories (id, kind) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_categories__id_kind ON categories (id, kind);

-- activity_records <- maint.activity_records
