    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    parent_activity_id TEXT CHECK (parent_activity_id IS NULL OR (length(parent_activity_id) = 36 AND parent_activity_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL DEFAULT 'other' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('service', 'inspection', 'repair', 'fuel', 'handover', 'note', 'other'))),
    category_label TEXT,
    title TEXT,
    occurred_at INTEGER NOT NULL,
    procedure_template_version_id TEXT CHECK (procedure_template_version_id IS NULL OR (length(procedure_template_version_id) = 36 AND procedure_template_version_id NOT GLOB '*[^0-9a-f-]*')),
    performed_by_user_id TEXT CHECK (performed_by_user_id IS NULL OR (length(performed_by_user_id) = 36 AND performed_by_user_id NOT GLOB '*[^0-9a-f-]*')),
    performed_by_name TEXT,
    provider_party_id TEXT CHECK (provider_party_id IS NULL OR (length(provider_party_id) = 36 AND provider_party_id NOT GLOB '*[^0-9a-f-]*')),
    provider_name TEXT,
    cost_mode TEXT NOT NULL DEFAULT 'simple' CHECK ((length(cost_mode) BETWEEN 1 AND 63 AND cost_mode GLOB '[a-z]*' AND cost_mode NOT GLOB '*[^a-z0-9_]*') AND (cost_mode IN ('simple', 'detailed'))),
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    exchange_rate TEXT CHECK (exchange_rate IS NULL OR (exchange_rate NOT GLOB '*[^0-9.-]*' AND length(exchange_rate) BETWEEN 1 AND 40)),
    overtime_multiplier TEXT CHECK (overtime_multiplier IS NULL OR ((overtime_multiplier NOT GLOB '*[^0-9.-]*' AND length(overtime_multiplier) BETWEEN 1 AND 40) AND (overtime_multiplier >= 1))),
    handover_id TEXT CHECK (handover_id IS NULL OR (length(handover_id) = 36 AND handover_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    notes TEXT,
    payload TEXT NOT NULL CHECK (json_valid(payload)),
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    CHECK (parent_activity_id IS NULL OR parent_activity_id <> id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (parent_activity_id) REFERENCES activity_records (id) ON DELETE RESTRICT,
    FOREIGN KEY (procedure_template_version_id) REFERENCES procedure_template_versions (id) ON DELETE RESTRICT,
    FOREIGN KEY (provider_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (handover_id) REFERENCES rental_handovers (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_line_id) REFERENCES rental_order_lines (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_activity_records__id_work_order_id ON activity_records (id, work_order_id);

-- attachments <- maint.attachments (server-only check 'one_object'; server-only check 'one_subject')
CREATE TABLE IF NOT EXISTS attachments (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    file_object_id TEXT CHECK (file_object_id IS NULL OR (length(file_object_id) = 36 AND file_object_id NOT GLOB '*[^0-9a-f-]*')),
    document_id TEXT CHECK (document_id IS NULL OR (length(document_id) = 36 AND document_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    activity_id TEXT CHECK (activity_id IS NULL OR (length(activity_id) = 36 AND activity_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    asset_loan_id TEXT CHECK (asset_loan_id IS NULL OR (length(asset_loan_id) = 36 AND asset_loan_id NOT GLOB '*[^0-9a-f-]*')),
    sort_order INTEGER,
    PRIMARY KEY (id),
    FOREIGN KEY (file_object_id) REFERENCES files (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (activity_id) REFERENCES activity_records (id) ON DELETE CASCADE,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE
) STRICT;

-- activity_cost_lines <- maint.activity_cost_lines
CREATE TABLE IF NOT EXISTS activity_cost_lines (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    activity_id TEXT NOT NULL CHECK (length(activity_id) = 36 AND activity_id NOT GLOB '*[^0-9a-f-]*'),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    project_id TEXT CHECK (project_id IS NULL OR (length(project_id) = 36 AND project_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('part', 'labor', 'misc'))),
    sort_order INTEGER NOT NULL DEFAULT 0,
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    stock_movement_line_id TEXT CHECK (stock_movement_line_id IS NULL OR (length(stock_movement_line_id) = 36 AND stock_movement_line_id NOT GLOB '*[^0-9a-f-]*')),
    performer_worker_id TEXT CHECK (performer_worker_id IS NULL OR (length(performer_worker_id) = 36 AND performer_worker_id NOT GLOB '*[^0-9a-f-]*')),
    description TEXT,
    quantity_micros INTEGER NOT NULL,
    uom_code TEXT,
    unit_cost TEXT CHECK (unit_cost IS NULL OR (unit_cost NOT GLOB '*[^0-9.-]*' AND length(unit_cost) BETWEEN 1 AND 40)),
    tax_amount_minor INTEGER,
    overtime INTEGER NOT NULL DEFAULT 0 CHECK (overtime IN (0, 1)),
    gl_account_id TEXT CHECK (gl_account_id IS NULL OR (length(gl_account_id) = 36 AND gl_account_id NOT GLOB '*[^0-9a-f-]*')),
    cost_status TEXT NOT NULL DEFAULT 'actual' CHECK ((length(cost_status) BETWEEN 1 AND 63 AND cost_status GLOB '[a-z]*' AND cost_status NOT GLOB '*[^a-z0-9_]*') AND (cost_status IN ('actual', 'estimate', 'committed'))),
    approved_by TEXT CHECK (approved_by IS NULL OR (length(approved_by) = 36 AND approved_by NOT GLOB '*[^0-9a-f-]*')),
    approved_at INTEGER,
    part_number TEXT,
    serial_number TEXT,
    lot_number TEXT,
    part_snapshot TEXT CHECK (part_snapshot IS NULL OR (json_valid(part_snapshot))),
    notes TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (activity_id) REFERENCES activity_records (id) ON DELETE CASCADE,
    FOREIGN KEY (activity_id, work_order_id) REFERENCES activity_records (id, work_order_id) ON DELETE CASCADE,
    FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (stock_movement_line_id) REFERENCES stock_movement_lines (id) ON DELETE RESTRICT,
    FOREIGN KEY (performer_worker_id) REFERENCES workers (id) ON DELETE RESTRICT
) STRICT;

-- asset_meters <- maint.asset_meters
CREATE TABLE IF NOT EXISTS asset_meters (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    meter_kind TEXT NOT NULL CHECK (length(meter_kind) BETWEEN 1 AND 63 AND meter_kind GLOB '[a-z]*' AND meter_kind NOT GLOB '*[^a-z0-9_]*'),
    unit TEXT NOT NULL CHECK (length(unit) BETWEEN 1 AND 63 AND unit GLOB '[a-z]*' AND unit NOT GLOB '*[^a-z0-9_]*'),
