CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_meters__asset_id_id ON asset_meters (asset_id, id);

-- meter_readings <- maint.meter_readings
CREATE TABLE IF NOT EXISTS meter_readings (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    meter_id TEXT NOT NULL CHECK (length(meter_id) = 36 AND meter_id NOT GLOB '*[^0-9a-f-]*'),
    value_micros INTEGER NOT NULL,
    read_at INTEGER NOT NULL,
    source TEXT NOT NULL DEFAULT 'manual' CHECK ((length(source) BETWEEN 1 AND 63 AND source GLOB '[a-z]*' AND source NOT GLOB '*[^a-z0-9_]*') AND (source IN ('manual', 'checkout', 'checkin', 'service', 'activity', 'import', 'telematics'))),
    activity_id TEXT CHECK (activity_id IS NULL OR (length(activity_id) = 36 AND activity_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    handover_id TEXT CHECK (handover_id IS NULL OR (length(handover_id) = 36 AND handover_id NOT GLOB '*[^0-9a-f-]*')),
    photo_file_id TEXT CHECK (photo_file_id IS NULL OR (length(photo_file_id) = 36 AND photo_file_id NOT GLOB '*[^0-9a-f-]*')),
    recorded_by TEXT CHECK (recorded_by IS NULL OR (length(recorded_by) = 36 AND recorded_by NOT GLOB '*[^0-9a-f-]*')),
    corrected_by TEXT CHECK (corrected_by IS NULL OR (length(corrected_by) = 36 AND corrected_by NOT GLOB '*[^0-9a-f-]*')),
    correction_reason TEXT,
    client_ref TEXT CHECK (client_ref IS NULL OR (length(client_ref) = 36 AND client_ref NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    FOREIGN KEY (asset_id, meter_id) REFERENCES asset_meters (asset_id, id) ON DELETE CASCADE,
    FOREIGN KEY (activity_id) REFERENCES activity_records (id) ON DELETE SET NULL,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_line_id) REFERENCES rental_order_lines (id) ON DELETE RESTRICT,
    FOREIGN KEY (handover_id) REFERENCES rental_handovers (id) ON DELETE RESTRICT,
    FOREIGN KEY (photo_file_id) REFERENCES files (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_meter_readings__client_ref ON meter_readings (client_ref);

-- work_orders <- maint.work_orders
CREATE TABLE IF NOT EXISTS work_orders (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 500),
    description TEXT,
    category_id TEXT CHECK (category_id IS NULL OR (length(category_id) = 36 AND category_id NOT GLOB '*[^0-9a-f-]*')),
    priority TEXT NOT NULL DEFAULT 'medium' CHECK ((length(priority) BETWEEN 1 AND 63 AND priority GLOB '[a-z]*' AND priority NOT GLOB '*[^a-z0-9_]*') AND (priority IN ('critical', 'high', 'medium', 'low'))),
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'pending_approval', 'open', 'scheduled', 'assigned', 'in_progress', 'on_hold', 'completed', 'closed', 'cancelled', 'skipped'))),
    complexity TEXT CHECK (complexity IS NULL OR ((length(complexity) BETWEEN 1 AND 63 AND complexity GLOB '[a-z]*' AND complexity NOT GLOB '*[^a-z0-9_]*') AND (complexity IN ('simple', 'standard', 'complex')))),
    approval_state TEXT CHECK (approval_state IS NULL OR (length(approval_state) BETWEEN 1 AND 63 AND approval_state GLOB '[a-z]*' AND approval_state NOT GLOB '*[^a-z0-9_]*')),
    requester_user_id TEXT CHECK (requester_user_id IS NULL OR (length(requester_user_id) = 36 AND requester_user_id NOT GLOB '*[^0-9a-f-]*')),
    assigned_worker_id TEXT CHECK (assigned_worker_id IS NULL OR (length(assigned_worker_id) = 36 AND assigned_worker_id NOT GLOB '*[^0-9a-f-]*')),
    assigned_team_id TEXT CHECK (assigned_team_id IS NULL OR (length(assigned_team_id) = 36 AND assigned_team_id NOT GLOB '*[^0-9a-f-]*')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    project_id TEXT CHECK (project_id IS NULL OR (length(project_id) = 36 AND project_id NOT GLOB '*[^0-9a-f-]*')),
    due_at INTEGER,
    planned_during_start INTEGER,
    planned_during_end INTEGER,
    timezone TEXT CHECK (timezone IS NULL OR (length(timezone) BETWEEN 1 AND 64)),
    started_at INTEGER,
    completed_at INTEGER,
    completion_activity_id TEXT CHECK (completion_activity_id IS NULL OR (length(completion_activity_id) = 36 AND completion_activity_id NOT GLOB '*[^0-9a-f-]*')),
    failure_value_id TEXT CHECK (failure_value_id IS NULL OR (length(failure_value_id) = 36 AND failure_value_id NOT GLOB '*[^0-9a-f-]*')),
    cause_value_id TEXT CHECK (cause_value_id IS NULL OR (length(cause_value_id) = 36 AND cause_value_id NOT GLOB '*[^0-9a-f-]*')),
    remedy_value_id TEXT CHECK (remedy_value_id IS NULL OR (length(remedy_value_id) = 36 AND remedy_value_id NOT GLOB '*[^0-9a-f-]*')),
    skip_reason_value_id TEXT CHECK (skip_reason_value_id IS NULL OR (length(skip_reason_value_id) = 36 AND skip_reason_value_id NOT GLOB '*[^0-9a-f-]*')),
    skip_reason TEXT,
    requires_permit INTEGER NOT NULL DEFAULT 0 CHECK (requires_permit IN (0, 1)),
    required_skills TEXT CHECK (required_skills IS NULL OR (json_valid(required_skills) AND json_type(required_skills) = 'array')),
    estimated_effort_minutes INTEGER CHECK (estimated_effort_minutes IS NULL OR (estimated_effort_minutes >= 0)),
    exclude_from_estimates INTEGER NOT NULL DEFAULT 0 CHECK (exclude_from_estimates IN (0, 1)),
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    dispatcher_notes TEXT,
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    CHECK (status <> 'skipped' OR skip_reason_value_id IS NOT NULL OR skip_reason IS NOT NULL),
    CHECK (status NOT IN ('completed', 'closed') OR completed_at IS NOT NULL),
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE SET NULL,
    FOREIGN KEY (assigned_worker_id) REFERENCES workers (id) ON DELETE SET NULL,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE SET NULL,
    FOREIGN KEY (completion_activity_id) REFERENCES activity_records (id) ON DELETE SET NULL,
    FOREIGN KEY (failure_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT,
    FOREIGN KEY (cause_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT,
    FOREIGN KEY (remedy_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT,
    FOREIGN KEY (skip_reason_value_id) REFERENCES reference_values (id) ON DELETE RESTRICT
) STRICT;

-- work_order_assets <- maint.work_order_assets
CREATE TABLE IF NOT EXISTS work_order_assets (
    created_at INTEGER NOT NULL,
    work_order_id TEXT NOT NULL CHECK (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*'),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (work_order_id, asset_id),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT
) STRICT, WITHOUT ROWID;

-- work_order_assignments <- maint.work_order_assignments
CREATE TABLE IF NOT EXISTS work_order_assignments (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    work_order_id TEXT NOT NULL CHECK (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*'),
    worker_id TEXT NOT NULL CHECK (length(worker_id) = 36 AND worker_id NOT GLOB '*[^0-9a-f-]*'),
    role TEXT NOT NULL DEFAULT 'lead' CHECK ((length(role) BETWEEN 1 AND 63 AND role GLOB '[a-z]*' AND role NOT GLOB '*[^a-z0-9_]*') AND (role IN ('lead', 'secondary', 'helper'))),
    acceptance_status TEXT NOT NULL DEFAULT 'assigned' CHECK (length(acceptance_status) BETWEEN 1 AND 63 AND acceptance_status GLOB '[a-z]*' AND acceptance_status NOT GLOB '*[^a-z0-9_]*'),
    assigned_by TEXT CHECK (assigned_by IS NULL OR (length(assigned_by) = 36 AND assigned_by NOT GLOB '*[^0-9a-f-]*')),
    estimated_hours TEXT CHECK (estimated_hours IS NULL OR (estimated_hours NOT GLOB '*[^0-9.-]*' AND length(estimated_hours) BETWEEN 1 AND 40)),
    sort_order INTEGER NOT NULL DEFAULT 0,
    notes TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (worker_id) REFERENCES workers (id) ON DELETE RESTRICT
) STRICT;

-- work_order_templates <- maint.work_order_templates
CREATE TABLE IF NOT EXISTS work_order_templates (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    title TEXT NOT NULL,
    title_template TEXT,
    description_template TEXT,
    category_id TEXT CHECK (category_id IS NULL OR (length(category_id) = 36 AND category_id NOT GLOB '*[^0-9a-f-]*')),
    priority TEXT CHECK (priority IS NULL OR ((length(priority) BETWEEN 1 AND 63 AND priority GLOB '[a-z]*' AND priority NOT GLOB '*[^a-z0-9_]*') AND (priority IN ('critical', 'high', 'medium', 'low')))),
    estimated_effort_minutes INTEGER,
    required_skills TEXT CHECK (required_skills IS NULL OR (json_valid(required_skills) AND json_type(required_skills) = 'array')),
    default_team_id TEXT CHECK (default_team_id IS NULL OR (length(default_team_id) = 36 AND default_team_id NOT GLOB '*[^0-9a-f-]*')),
    procedure_template_id TEXT CHECK (procedure_template_id IS NULL OR (length(procedure_template_id) = 36 AND procedure_template_id NOT GLOB '*[^0-9a-f-]*')),
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE SET NULL,
    FOREIGN KEY (procedure_template_id) REFERENCES procedure_templates (id) ON DELETE SET NULL
) STRICT;

-- work_order_sla_policies <- maint.work_order_sla_policies
CREATE TABLE IF NOT EXISTS work_order_sla_policies (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    priority TEXT NOT NULL CHECK ((length(priority) BETWEEN 1 AND 63 AND priority GLOB '[a-z]*' AND priority NOT GLOB '*[^a-z0-9_]*') AND (priority IN ('critical', 'high', 'medium', 'low'))),
    respond_hours INTEGER CHECK (respond_hours IS NULL OR (respond_hours > 0)),
    resolve_hours INTEGER CHECK (resolve_hours IS NULL OR (resolve_hours > 0)),
    PRIMARY KEY (priority)
) STRICT;

-- procedure_templates <- maint.procedure_templates
CREATE TABLE IF NOT EXISTS procedure_templates (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    name TEXT NOT NULL,
    description TEXT,
    current_version_id TEXT CHECK (current_version_id IS NULL OR (length(current_version_id) = 36 AND current_version_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id)
) STRICT;

-- procedure_template_versions <- maint.procedure_template_versions
CREATE TABLE IF NOT EXISTS procedure_template_versions (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    template_id TEXT CHECK (template_id IS NULL OR (length(template_id) = 36 AND template_id NOT GLOB '*[^0-9a-f-]*')),
    version_no INTEGER NOT NULL DEFAULT 1 CHECK (version_no >= 1),
    status TEXT NOT NULL DEFAULT 'draft' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'published', 'inline'))),
    published_at INTEGER,
    PRIMARY KEY (id),
    CHECK ((status = 'inline') = (template_id IS NULL)),
    CHECK (status <> 'published' OR published_at IS NOT NULL),
    FOREIGN KEY (template_id) REFERENCES procedure_templates (id) ON DELETE RESTRICT
) STRICT;

-- procedure_template_rows <- maint.procedure_template_rows
CREATE TABLE IF NOT EXISTS procedure_template_rows (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    version_id TEXT NOT NULL CHECK (length(version_id) = 36 AND version_id NOT GLOB '*[^0-9a-f-]*'),
    sort_order INTEGER NOT NULL,
    row_type TEXT NOT NULL DEFAULT 'step' CHECK (length(row_type) BETWEEN 1 AND 63 AND row_type GLOB '[a-z]*' AND row_type NOT GLOB '*[^a-z0-9_]*'),
    label TEXT NOT NULL,
    description TEXT,
    required INTEGER NOT NULL DEFAULT 0 CHECK (required IN (0, 1)),
    urls TEXT CHECK (urls IS NULL OR (json_valid(urls) AND json_type(urls) = 'array')),
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    FOREIGN KEY (version_id) REFERENCES procedure_template_versions (id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_procedure_template_rows__version_id_id ON procedure_template_rows (version_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_procedure_template_rows__version_id_sort_order ON procedure_template_rows (version_id, sort_order);

-- procedure_instances <- maint.procedure_instances
CREATE TABLE IF NOT EXISTS procedure_instances (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    version_id TEXT NOT NULL CHECK (length(version_id) = 36 AND version_id NOT GLOB '*[^0-9a-f-]*'),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    activity_id TEXT CHECK (activity_id IS NULL OR (length(activity_id) = 36 AND activity_id NOT GLOB '*[^0-9a-f-]*')),
    template_name TEXT,
    PRIMARY KEY (id),
    CHECK ((work_order_id IS NULL) <> (activity_id IS NULL)),
    FOREIGN KEY (version_id) REFERENCES procedure_template_versions (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (activity_id) REFERENCES activity_records (id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_procedure_instances__id_version_id ON procedure_instances (id, version_id);

-- procedure_responses <- maint.procedure_responses
CREATE TABLE IF NOT EXISTS procedure_responses (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    instance_id TEXT NOT NULL CHECK (length(instance_id) = 36 AND instance_id NOT GLOB '*[^0-9a-f-]*'),
    version_id TEXT NOT NULL CHECK (length(version_id) = 36 AND version_id NOT GLOB '*[^0-9a-f-]*'),
    row_id TEXT NOT NULL CHECK (length(row_id) = 36 AND row_id NOT GLOB '*[^0-9a-f-]*'),
    response TEXT CHECK (response IS NULL OR (json_valid(response))),
    pass_fail TEXT CHECK (pass_fail IS NULL OR ((length(pass_fail) BETWEEN 1 AND 63 AND pass_fail GLOB '[a-z]*' AND pass_fail NOT GLOB '*[^a-z0-9_]*') AND (pass_fail IN ('pass', 'fail', 'na')))),
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    completed_by TEXT CHECK (completed_by IS NULL OR (length(completed_by) = 36 AND completed_by NOT GLOB '*[^0-9a-f-]*')),
    completed_at INTEGER,
    notes TEXT,
    attachment_file_id TEXT CHECK (attachment_file_id IS NULL OR (length(attachment_file_id) = 36 AND attachment_file_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    FOREIGN KEY (instance_id, version_id) REFERENCES procedure_instances (id, version_id) ON DELETE CASCADE,
    FOREIGN KEY (version_id, row_id) REFERENCES procedure_template_rows (version_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (attachment_file_id) REFERENCES files (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_procedure_responses__instance_id_row_id ON procedure_responses (instance_id, row_id);

-- inspection_defects <- maint.inspection_defects
CREATE TABLE IF NOT EXISTS inspection_defects (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    item_id TEXT,
    item_key TEXT NOT NULL,
    label TEXT,
    corner_label TEXT,
    section_title TEXT,
    bucket TEXT NOT NULL CHECK ((length(bucket) BETWEEN 1 AND 63 AND bucket GLOB '[a-z]*' AND bucket NOT GLOB '*[^a-z0-9_]*') AND (bucket IN ('nr', 'm'))),
    severity TEXT CHECK (severity IS NULL OR (length(severity) BETWEEN 1 AND 63 AND severity GLOB '[a-z]*' AND severity NOT GLOB '*[^a-z0-9_]*')),
    note TEXT,
    location_label TEXT,
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('open', 'monitoring', 'repaired', 'deferred'))),
    source_activity_id TEXT CHECK (source_activity_id IS NULL OR (length(source_activity_id) = 36 AND source_activity_id NOT GLOB '*[^0-9a-f-]*')),
    reported_at INTEGER NOT NULL,
    last_seen_activity_id TEXT CHECK (last_seen_activity_id IS NULL OR (length(last_seen_activity_id) = 36 AND last_seen_activity_id NOT GLOB '*[^0-9a-f-]*')),
    last_seen_at INTEGER,
    resolved_at INTEGER,
    resolved_by TEXT CHECK (resolved_by IS NULL OR (length(resolved_by) = 36 AND resolved_by NOT GLOB '*[^0-9a-f-]*')),
    resolved_activity_id TEXT CHECK (resolved_activity_id IS NULL OR (length(resolved_activity_id) = 36 AND resolved_activity_id NOT GLOB '*[^0-9a-f-]*')),
    resolution_note TEXT,
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (status <> 'repaired' OR resolved_at IS NOT NULL),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (source_activity_id) REFERENCES activity_records (id) ON DELETE SET NULL,
    FOREIGN KEY (last_seen_activity_id) REFERENCES activity_records (id) ON DELETE SET NULL,
    FOREIGN KEY (resolved_activity_id) REFERENCES activity_records (id) ON DELETE SET NULL,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE SET NULL
) STRICT;

-- work_permits <- maint.work_permits
CREATE TABLE IF NOT EXISTS work_permits (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    work_order_id TEXT NOT NULL CHECK (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*'),
    permit_type TEXT NOT NULL CHECK (length(permit_type) BETWEEN 1 AND 63 AND permit_type GLOB '[a-z]*' AND permit_type NOT GLOB '*[^a-z0-9_]*'),
    hazards TEXT NOT NULL CHECK (json_valid(hazards)),
    precautions TEXT NOT NULL CHECK (json_valid(precautions)),
    valid_during_start INTEGER,
    valid_during_end INTEGER,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*'),
    notes TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE
) STRICT;

-- rca_reports <- maint.rca_reports
CREATE TABLE IF NOT EXISTS rca_reports (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    work_order_id TEXT NOT NULL CHECK (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*'),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    problem_description TEXT,
    immediate_action TEXT,
    root_cause TEXT,
    corrective_action TEXT,
    preventive_action TEXT,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*'),
    completed_at INTEGER,
    completed_by TEXT CHECK (completed_by IS NULL OR (length(completed_by) = 36 AND completed_by NOT GLOB '*[^0-9a-f-]*')),
    ai_draft TEXT,
    ai_model TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE SET NULL
) STRICT;

-- pm_plans <- maint.pm_plans
CREATE TABLE IF NOT EXISTS pm_plans (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    title TEXT NOT NULL,
    description TEXT,
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_template_id TEXT CHECK (work_order_template_id IS NULL OR (length(work_order_template_id) = 36 AND work_order_template_id NOT GLOB '*[^0-9a-f-]*')),
    timezone TEXT CHECK (timezone IS NULL OR (length(timezone) BETWEEN 1 AND 64)),
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    end_type TEXT NOT NULL DEFAULT 'never' CHECK (length(end_type) BETWEEN 1 AND 63 AND end_type GLOB '[a-z]*' AND end_type NOT GLOB '*[^a-z0-9_]*'),
    end_count INTEGER CHECK (end_count IS NULL OR (end_count > 0)),
    end_on TEXT CHECK (end_on IS NULL OR (end_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    cycle_no INTEGER NOT NULL DEFAULT 0 CHECK (cycle_no >= 0),
    last_completed_at INTEGER,
    calendar_anchor_at INTEGER,
    ai_suggested INTEGER NOT NULL DEFAULT 0 CHECK (ai_suggested IN (0, 1)),
    ai_suggestion_context TEXT CHECK (ai_suggestion_context IS NULL OR (json_valid(ai_suggestion_context))),
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_template_id) REFERENCES work_order_templates (id) ON DELETE SET NULL
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_pm_plans__id_asset_id ON pm_plans (id, asset_id);

-- pm_triggers <- maint.pm_triggers
CREATE TABLE IF NOT EXISTS pm_triggers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    pm_plan_id TEXT NOT NULL CHECK (length(pm_plan_id) = 36 AND pm_plan_id NOT GLOB '*[^0-9a-f-]*'),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('calendar', 'interval', 'meter'))),
    priority INTEGER NOT NULL DEFAULT 0,
    rrule TEXT,
    interval_value INTEGER CHECK (interval_value IS NULL OR (interval_value > 0)),
    interval_unit TEXT CHECK (interval_unit IS NULL OR (length(interval_unit) BETWEEN 1 AND 63 AND interval_unit GLOB '[a-z]*' AND interval_unit NOT GLOB '*[^a-z0-9_]*')),
    cycle_level INTEGER,
    meter_id TEXT CHECK (meter_id IS NULL OR (length(meter_id) = 36 AND meter_id NOT GLOB '*[^0-9a-f-]*')),
    meter_condition TEXT CHECK (meter_condition IS NULL OR (length(meter_condition) BETWEEN 1 AND 63 AND meter_condition GLOB '[a-z]*' AND meter_condition NOT GLOB '*[^a-z0-9_]*')),
    meter_interval_micros INTEGER,
    threshold_value_micros INTEGER,
    meter_anchor_value_micros INTEGER,
    next_due_at INTEGER,
    next_due_value_micros INTEGER,
    generate_once INTEGER NOT NULL DEFAULT 0 CHECK (generate_once IN (0, 1)),
    last_satisfied_at INTEGER,
    last_observed_value_micros INTEGER,
    work_order_template_id TEXT CHECK (work_order_template_id IS NULL OR (length(work_order_template_id) = 36 AND work_order_template_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (kind <> 'calendar' OR rrule IS NOT NULL),
    CHECK (kind <> 'interval' OR (interval_value IS NOT NULL AND interval_unit IS NOT NULL)),
    CHECK (kind <> 'meter' OR (meter_id IS NOT NULL AND asset_id IS NOT NULL AND (meter_interval_micros IS NOT NULL OR threshold_value_micros IS NOT NULL))),
    FOREIGN KEY (pm_plan_id) REFERENCES pm_plans (id) ON DELETE CASCADE,
    FOREIGN KEY (pm_plan_id, asset_id) REFERENCES pm_plans (id, asset_id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id, meter_id) REFERENCES asset_meters (asset_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_template_id) REFERENCES work_order_templates (id) ON DELETE SET NULL
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_pm_triggers__pm_plan_id_id ON pm_triggers (pm_plan_id, id);

-- pm_occurrences <- maint.pm_occurrences
CREATE TABLE IF NOT EXISTS pm_occurrences (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    pm_plan_id TEXT NOT NULL CHECK (length(pm_plan_id) = 36 AND pm_plan_id NOT GLOB '*[^0-9a-f-]*'),
    occurrence_key TEXT NOT NULL,
    trigger_id TEXT CHECK (trigger_id IS NULL OR (length(trigger_id) = 36 AND trigger_id NOT GLOB '*[^0-9a-f-]*')),
    cycle_no INTEGER NOT NULL CHECK (cycle_no >= 1),
    state TEXT NOT NULL DEFAULT 'open' CHECK ((length(state) BETWEEN 1 AND 63 AND state GLOB '[a-z]*' AND state NOT GLOB '*[^a-z0-9_]*') AND (state IN ('open', 'completed', 'skipped', 'cancelled'))),
    due_at INTEGER,
    due_value_micros INTEGER,
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    opened_at INTEGER NOT NULL,
    closed_at INTEGER,
    PRIMARY KEY (id),
    CHECK ((state = 'open') = (closed_at IS NULL)),
    FOREIGN KEY (pm_plan_id) REFERENCES pm_plans (id) ON DELETE CASCADE,
    FOREIGN KEY (pm_plan_id, trigger_id) REFERENCES pm_triggers (pm_plan_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_pm_occurrences__pm_plan_id_occurrence_key ON pm_occurrences (pm_plan_id, occurrence_key);
CREATE UNIQUE INDEX IF NOT EXISTS ux_pm_occurrences__work_order_id ON pm_occurrences (work_order_id);

-- workers <- maint.workers (server-only check 'has_person')
CREATE TABLE IF NOT EXISTS workers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    user_id TEXT CHECK (user_id IS NULL OR (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*')),
    operator_profile_id TEXT CHECK (operator_profile_id IS NULL OR (length(operator_profile_id) = 36 AND operator_profile_id NOT GLOB '*[^0-9a-f-]*')),
    calendar_id TEXT CHECK (calendar_id IS NULL OR (length(calendar_id) = 36 AND calendar_id NOT GLOB '*[^0-9a-f-]*')),
    worker_kind TEXT NOT NULL DEFAULT 'member' CHECK ((length(worker_kind) BETWEEN 1 AND 63 AND worker_kind GLOB '[a-z]*' AND worker_kind NOT GLOB '*[^a-z0-9_]*') AND (worker_kind IN ('member', 'contractor'))),
    role TEXT CHECK (role IS NULL OR (length(role) BETWEEN 1 AND 63 AND role GLOB '[a-z]*' AND role NOT GLOB '*[^a-z0-9_]*')),
    status TEXT NOT NULL DEFAULT 'active' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('invited', 'active', 'inactive', 'removed'))),
    display_name TEXT,
    invite_email TEXT CHECK (invite_email IS NULL OR (invite_email = lower(trim(invite_email)) AND instr(invite_email, '@') > 1)),
    invitation_id TEXT CHECK (invitation_id IS NULL OR (length(invitation_id) = 36 AND invitation_id NOT GLOB '*[^0-9a-f-]*')),
    skills TEXT CHECK (skills IS NULL OR (json_valid(skills) AND json_type(skills) = 'array')),
    max_active_work_orders INTEGER CHECK (max_active_work_orders IS NULL OR (max_active_work_orders >= 0)),
    available INTEGER NOT NULL DEFAULT 1 CHECK (available IN (0, 1)),
    speed_factor TEXT CHECK (speed_factor IS NULL OR ((speed_factor NOT GLOB '*[^0-9.-]*' AND length(speed_factor) BETWEEN 1 AND 40) AND (speed_factor > 0))),
    speed_factor_sample_n INTEGER,
    speed_factor_updated_at INTEGER,
    home_location_id TEXT CHECK (home_location_id IS NULL OR (length(home_location_id) = 36 AND home_location_id NOT GLOB '*[^0-9a-f-]*')),
    employed_from INTEGER,
    employed_until INTEGER,
    notes TEXT,
    attributes TEXT NOT NULL CHECK (json_valid(attributes)),
    PRIMARY KEY (id),
    FOREIGN KEY (home_location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_workers__id_calendar_id ON workers (id, calendar_id);

-- work_assignments <- maint.work_assignments (server-only check 'subject_shape')
CREATE TABLE IF NOT EXISTS work_assignments (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    worker_id TEXT NOT NULL CHECK (length(worker_id) = 36 AND worker_id NOT GLOB '*[^0-9a-f-]*'),
    calendar_id TEXT NOT NULL CHECK (length(calendar_id) = 36 AND calendar_id NOT GLOB '*[^0-9a-f-]*'),
    kind TEXT NOT NULL DEFAULT 'work' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('work', 'unavailable', 'travel'))),
    blocking INTEGER NOT NULL DEFAULT 1 CHECK (blocking IN (0, 1)),
    during_start INTEGER NOT NULL,
    during_end INTEGER,
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_assignment_id TEXT CHECK (work_order_assignment_id IS NULL OR (length(work_order_assignment_id) = 36 AND work_order_assignment_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    labor_order_line_id TEXT CHECK (labor_order_line_id IS NULL OR (length(labor_order_line_id) = 36 AND labor_order_line_id NOT GLOB '*[^0-9a-f-]*')),
    cert_warnings TEXT CHECK (cert_warnings IS NULL OR (json_valid(cert_warnings))),
    released_at INTEGER,
    released_by TEXT CHECK (released_by IS NULL OR (length(released_by) = 36 AND released_by NOT GLOB '*[^0-9a-f-]*')),
    cancelled_at INTEGER,
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (order_line_id IS NULL OR order_id IS NOT NULL),
    FOREIGN KEY (worker_id, calendar_id) REFERENCES workers (id, calendar_id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (work_order_assignment_id) REFERENCES work_order_assignments (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_line_id) REFERENCES rental_order_lines (id) ON DELETE RESTRICT,
    FOREIGN KEY (labor_order_line_id) REFERENCES rental_order_lines (id) ON DELETE RESTRICT
) STRICT;

-- time_entries <- maint.time_entries (server-only check 'open_iff_running'; server-only check 'break_fits')
CREATE TABLE IF NOT EXISTS time_entries (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    worker_id TEXT NOT NULL CHECK (length(worker_id) = 36 AND worker_id NOT GLOB '*[^0-9a-f-]*'),
    calendar_id TEXT NOT NULL CHECK (length(calendar_id) = 36 AND calendar_id NOT GLOB '*[^0-9a-f-]*'),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    work_assignment_id TEXT CHECK (work_assignment_id IS NULL OR (length(work_assignment_id) = 36 AND work_assignment_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    work_date TEXT CHECK (work_date IS NULL OR (work_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    during_start INTEGER NOT NULL,
    during_end INTEGER,
    break_minutes INTEGER NOT NULL DEFAULT 0 CHECK (break_minutes >= 0),
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('open', 'submitted', 'approved', 'rejected'))),
    approved_by TEXT CHECK (approved_by IS NULL OR (length(approved_by) = 36 AND approved_by NOT GLOB '*[^0-9a-f-]*')),
    approved_at INTEGER,
    reject_reason TEXT,
    notes TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (worker_id, calendar_id) REFERENCES workers (id, calendar_id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_assignment_id) REFERENCES work_assignments (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT
) STRICT;

-- approval_requests <- core.approval_requests (server-only check 'one_subject')
CREATE TABLE IF NOT EXISTS approval_requests (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    subject_kind TEXT NOT NULL CHECK ((length(subject_kind) BETWEEN 1 AND 63 AND subject_kind GLOB '[a-z]*' AND subject_kind NOT GLOB '*[^a-z0-9_]*') AND (subject_kind IN ('work_order', 'work_order_cost', 'purchase_order'))),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    purchase_order_id TEXT CHECK (purchase_order_id IS NULL OR (length(purchase_order_id) = 36 AND purchase_order_id NOT GLOB '*[^0-9a-f-]*')),
    rule_id TEXT CHECK (rule_id IS NULL OR (length(rule_id) = 36 AND rule_id NOT GLOB '*[^0-9a-f-]*')),
    requested_amount_minor INTEGER,
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    status TEXT NOT NULL DEFAULT 'pending' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('pending', 'approved', 'rejected', 'cancelled', 'expired'))),
    requested_by TEXT CHECK (requested_by IS NULL OR (length(requested_by) = 36 AND requested_by NOT GLOB '*[^0-9a-f-]*')),
    requested_at INTEGER NOT NULL,
    assigned_approver_user_id TEXT CHECK (assigned_approver_user_id IS NULL OR (length(assigned_approver_user_id) = 36 AND assigned_approver_user_id NOT GLOB '*[^0-9a-f-]*')),
    decided_at INTEGER,
    PRIMARY KEY (id),
    CHECK ((subject_kind = 'purchase_order') = (purchase_order_id IS NOT NULL)),
    CHECK (status IN ('pending') OR decided_at IS NOT NULL),
    CHECK (requested_amount_minor IS NULL OR currency IS NOT NULL),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id) ON DELETE RESTRICT
) STRICT;

-- approval_decisions <- core.approval_decisions
CREATE TABLE IF NOT EXISTS approval_decisions (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    request_id TEXT NOT NULL CHECK (length(request_id) = 36 AND request_id NOT GLOB '*[^0-9a-f-]*'),
    approver_user_id TEXT NOT NULL CHECK (length(approver_user_id) = 36 AND approver_user_id NOT GLOB '*[^0-9a-f-]*'),
    decision TEXT NOT NULL CHECK ((length(decision) BETWEEN 1 AND 63 AND decision GLOB '[a-z]*' AND decision NOT GLOB '*[^a-z0-9_]*') AND (decision IN ('approved', 'rejected'))),
    comment TEXT,
    decided_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY (request_id) REFERENCES approval_requests (id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_approval_decisions__request_id_approver_user_id ON approval_decisions (request_id, approver_user_id);

-- comments <- platform.comments (server-only check 'one_subject')
CREATE TABLE IF NOT EXISTS comments (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    purchase_order_id TEXT CHECK (purchase_order_id IS NULL OR (length(purchase_order_id) = 36 AND purchase_order_id NOT GLOB '*[^0-9a-f-]*')),
    invoice_id TEXT CHECK (invoice_id IS NULL OR (length(invoice_id) = 36 AND invoice_id NOT GLOB '*[^0-9a-f-]*')),
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    author_user_id TEXT CHECK (author_user_id IS NULL OR (length(author_user_id) = 36 AND author_user_id NOT GLOB '*[^0-9a-f-]*')),
    body TEXT,
    comment_type TEXT NOT NULL DEFAULT 'comment' CHECK (length(comment_type) BETWEEN 1 AND 63 AND comment_type GLOB '[a-z]*' AND comment_type NOT GLOB '*[^a-z0-9_]*'),
    audience TEXT NOT NULL DEFAULT 'all' CHECK ((length(audience) BETWEEN 1 AND 63 AND audience GLOB '[a-z]*' AND audience NOT GLOB '*[^a-z0-9_]*') AND (audience IN ('internal', 'all'))),
    photo_file_id TEXT CHECK (photo_file_id IS NULL OR (length(photo_file_id) = 36 AND photo_file_id NOT GLOB '*[^0-9a-f-]*')),
    voice_file_id TEXT CHECK (voice_file_id IS NULL OR (length(voice_file_id) = 36 AND voice_file_id NOT GLOB '*[^0-9a-f-]*')),
    attachment_file_id TEXT CHECK (attachment_file_id IS NULL OR (length(attachment_file_id) = 36 AND attachment_file_id NOT GLOB '*[^0-9a-f-]*')),
    status_meta TEXT CHECK (status_meta IS NULL OR (json_valid(status_meta))),
    PRIMARY KEY (id),
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE CASCADE,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (photo_file_id) REFERENCES files (id) ON DELETE RESTRICT,
    FOREIGN KEY (voice_file_id) REFERENCES files (id) ON DELETE RESTRICT,
    FOREIGN KEY (attachment_file_id) REFERENCES files (id) ON DELETE RESTRICT
) STRICT;

-- comment_mentions <- platform.comment_mentions
CREATE TABLE IF NOT EXISTS comment_mentions (
    created_at INTEGER NOT NULL,
    comment_id TEXT NOT NULL CHECK (length(comment_id) = 36 AND comment_id NOT GLOB '*[^0-9a-f-]*'),
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    PRIMARY KEY (comment_id, user_id),
    FOREIGN KEY (comment_id) REFERENCES comments (id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

-- comment_reactions <- platform.comment_reactions
CREATE TABLE IF NOT EXISTS comment_reactions (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    comment_id TEXT NOT NULL CHECK (length(comment_id) = 36 AND comment_id NOT GLOB '*[^0-9a-f-]*'),
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    emoji TEXT NOT NULL CHECK (length(emoji) BETWEEN 1 AND 32),
    PRIMARY KEY (id),
    FOREIGN KEY (comment_id) REFERENCES comments (id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_comment_reactions__comment_id_user_id_emoji ON comment_reactions (comment_id, user_id, emoji);

-- projects <- maint.projects
CREATE TABLE IF NOT EXISTS projects (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    number TEXT NOT NULL,
    name TEXT NOT NULL,
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    customer_name_snapshot TEXT,
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    site_note TEXT,
    start_on TEXT CHECK (start_on IS NULL OR (start_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    end_on TEXT CHECK (end_on IS NULL OR (end_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    status TEXT NOT NULL DEFAULT 'active' CHECK (length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*'),
    budget_minor INTEGER,
    currency TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*')),
    budget_alert_pct TEXT CHECK (budget_alert_pct IS NULL OR ((budget_alert_pct NOT GLOB '*[^0-9.-]*' AND length(budget_alert_pct) BETWEEN 1 AND 40) AND (budget_alert_pct BETWEEN 0 AND 100))),
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (end_on IS NULL OR start_on IS NULL OR end_on >= start_on),
    CHECK (budget_minor IS NULL OR currency IS NOT NULL),
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT
) STRICT;

-- calendar_links <- projection-only
CREATE TABLE IF NOT EXISTS calendar_links (
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    device_install_id TEXT NOT NULL,
    provider TEXT NOT NULL CHECK (length(provider) BETWEEN 1 AND 63 AND provider GLOB '[a-z]*' AND provider NOT GLOB '*[^a-z0-9_]*'),
    provider_account TEXT NOT NULL,
    provider_calendar_id TEXT NOT NULL,
    source_kind TEXT NOT NULL CHECK (length(source_kind) BETWEEN 1 AND 63 AND source_kind GLOB '[a-z]*' AND source_kind NOT GLOB '*[^a-z0-9_]*'),
    source_id TEXT NOT NULL CHECK (length(source_id) = 36 AND source_id NOT GLOB '*[^0-9a-f-]*'),
    occurrence_key TEXT NOT NULL,
    external_event_id TEXT,
    etag TEXT,
    last_pushed_at INTEGER,
    PRIMARY KEY (user_id, device_install_id, provider, provider_account, provider_calendar_id, source_kind, source_id, occurrence_key)
) STRICT;

-- ================================================= area rental

-- rental_classes <- rental.rental_classes
CREATE TABLE IF NOT EXISTS rental_classes (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    category_id TEXT CHECK (category_id IS NULL OR (length(category_id) = 36 AND category_id NOT GLOB '*[^0-9a-f-]*')),
    name TEXT NOT NULL,
    name_i18n TEXT NOT NULL CHECK (json_valid(name_i18n) AND json_type(name_i18n) = 'object'),
    description_i18n TEXT NOT NULL CHECK (json_valid(description_i18n) AND json_type(description_i18n) = 'object'),
    tracking TEXT NOT NULL DEFAULT 'serialized' CHECK ((length(tracking) BETWEEN 1 AND 63 AND tracking GLOB '[a-z]*' AND tracking NOT GLOB '*[^a-z0-9_]*') AND (tracking IN ('serialized', 'bulk'))),
    bulk_product_id TEXT CHECK (bulk_product_id IS NULL OR (length(bulk_product_id) = 36 AND bulk_product_id NOT GLOB '*[^0-9a-f-]*')),
    specs TEXT NOT NULL CHECK (json_valid(specs)),
    buffer_minutes INTEGER,
    deposit_minor INTEGER,
    deposit_currency TEXT CHECK (deposit_currency IS NULL OR (length(deposit_currency) = 3 AND deposit_currency NOT GLOB '*[^A-Z]*')),
    checkout_template_id TEXT CHECK (checkout_template_id IS NULL OR (length(checkout_template_id) = 36 AND checkout_template_id NOT GLOB '*[^0-9a-f-]*')),
    checkin_template_id TEXT CHECK (checkin_template_id IS NULL OR (length(checkin_template_id) = 36 AND checkin_template_id NOT GLOB '*[^0-9a-f-]*')),
    min_driver_age INTEGER,
    public INTEGER NOT NULL DEFAULT 0 CHECK (public IN (0, 1)),
    meter_kind TEXT CHECK (meter_kind IS NULL OR ((length(meter_kind) BETWEEN 1 AND 63 AND meter_kind GLOB '[a-z]*' AND meter_kind NOT GLOB '*[^a-z0-9_]*') AND (meter_kind IN ('distance', 'hours', 'none')))),
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    hidden INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0, 1)),
    auto_created INTEGER NOT NULL DEFAULT 0 CHECK (auto_created IN (0, 1)),
    source_model_id TEXT CHECK (source_model_id IS NULL OR (length(source_model_id) = 36 AND source_model_id NOT GLOB '*[^0-9a-f-]*')),
    source_asset_type TEXT,
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    meter_requirement TEXT,
    meter_unit TEXT,
    meter_max_per_day_micros INTEGER,
    PRIMARY KEY (id),
    CHECK ((tracking = 'bulk') = (bulk_product_id IS NOT NULL)),
    CHECK (buffer_minutes IS NULL OR buffer_minutes BETWEEN 0 AND 10080),
    CHECK ((deposit_minor IS NULL) = (deposit_currency IS NULL) AND (deposit_minor IS NULL OR deposit_minor >= 0)),
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT,
    FOREIGN KEY (bulk_product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_classes__name ON rental_classes (name);

-- rental_rate_tiers <- rental.rental_rate_tiers (server-only check 'one_owner')
CREATE TABLE IF NOT EXISTS rental_rate_tiers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    rate_card_id TEXT CHECK (rate_card_id IS NULL OR (length(rate_card_id) = 36 AND rate_card_id NOT GLOB '*[^0-9a-f-]*')),
    price_list_item_id TEXT CHECK (price_list_item_id IS NULL OR (length(price_list_item_id) = 36 AND price_list_item_id NOT GLOB '*[^0-9a-f-]*')),
    kit_id TEXT CHECK (kit_id IS NULL OR (length(kit_id) = 36 AND kit_id NOT GLOB '*[^0-9a-f-]*')),
    period_code TEXT NOT NULL CHECK ((length(period_code) BETWEEN 1 AND 63 AND period_code GLOB '[a-z]*' AND period_code NOT GLOB '*[^a-z0-9_]*') AND (period_code IN ('min_charge', 'hour', 'four_hour', 'eight_hour', 'day', 'weekend', 'week', 'four_week', 'month', 'unit'))),
    amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),
    PRIMARY KEY (id)
) STRICT;

-- rental_orders <- rental.rental_orders
CREATE TABLE IF NOT EXISTS rental_orders (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    status TEXT NOT NULL DEFAULT 'draft' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'quoted', 'held', 'reserved', 'on_rent', 'off_rent_requested', 'returned', 'closed', 'cancelled'))),
    walk_in_name TEXT,
    billable INTEGER NOT NULL DEFAULT 1 CHECK (billable IN (0, 1)),
    notes TEXT,
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    number TEXT NOT NULL,
    quote_number TEXT,
    contact_id TEXT CHECK (contact_id IS NULL OR (length(contact_id) = 36 AND contact_id NOT GLOB '*[^0-9a-f-]*')),
    site_location_id TEXT CHECK (site_location_id IS NULL OR (length(site_location_id) = 36 AND site_location_id NOT GLOB '*[^0-9a-f-]*')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    locale TEXT NOT NULL DEFAULT 'en' CHECK (length(locale) BETWEEN 2 AND 35),
    start_at INTEGER,
    end_at INTEGER,
    off_rent_at INTEGER,
    off_rent_by TEXT,
    quote_expires_at INTEGER,
    hold_expires_at INTEGER,
    fulfilment TEXT NOT NULL DEFAULT 'pickup' CHECK ((length(fulfilment) BETWEEN 1 AND 63 AND fulfilment GLOB '[a-z]*' AND fulfilment NOT GLOB '*[^a-z0-9_]*') AND (fulfilment IN ('pickup', 'delivery'))),
    po_number TEXT,
    reference TEXT,
    internal_notes TEXT,
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    terms_template_id TEXT CHECK (terms_template_id IS NULL OR (length(terms_template_id) = 36 AND terms_template_id NOT GLOB '*[^0-9a-f-]*')),
    terms_version INTEGER,
    subtotal_minor INTEGER NOT NULL DEFAULT 0,
    discount_minor INTEGER NOT NULL DEFAULT 0,
    tax_minor INTEGER NOT NULL DEFAULT 0,
    total_minor INTEGER NOT NULL DEFAULT 0,
    deposit_required_minor INTEGER NOT NULL DEFAULT 0,
    tax_summary TEXT NOT NULL CHECK (json_valid(tax_summary)),
    cancel_reason TEXT,
    source TEXT NOT NULL DEFAULT 'staff' CHECK ((length(source) BETWEEN 1 AND 63 AND source GLOB '[a-z]*' AND source NOT GLOB '*[^a-z0-9_]*') AND (source IN ('staff', 'storefront', 'portal', 'api', 'legacy', 'marketplace', 'network'))),
    needs_review INTEGER NOT NULL DEFAULT 0 CHECK (needs_review IN (0, 1)),
    review_reason TEXT,
    instant_book_status TEXT CHECK (instant_book_status IS NULL OR (length(instant_book_status) BETWEEN 1 AND 63 AND instant_book_status GLOB '[a-z]*' AND instant_book_status NOT GLOB '*[^a-z0-9_]*')),
    network_request_id TEXT CHECK (network_request_id IS NULL OR (length(network_request_id) = 36 AND network_request_id NOT GLOB '*[^0-9a-f-]*')),
    origin_channel TEXT CHECK (origin_channel IS NULL OR (length(origin_channel) BETWEEN 1 AND 63 AND origin_channel GLOB '[a-z]*' AND origin_channel NOT GLOB '*[^a-z0-9_]*')),
    project_id TEXT CHECK (project_id IS NULL OR (length(project_id) = 36 AND project_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL DEFAULT 'standard' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('standard', 'long_term', 'subrent_out'))),
    site_party_location_id TEXT CHECK (site_party_location_id IS NULL OR (length(site_party_location_id) = 36 AND site_party_location_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK ((site_location_id IS NULL) = (site_party_location_id IS NULL)),
    CHECK (status = 'draft' OR number IS NOT NULL),
    CHECK (start_at IS NULL OR end_at IS NULL OR start_at < end_at),
    CHECK (customer_party_id IS NOT NULL OR walk_in_name IS NOT NULL OR status IN ('draft', 'quoted', 'cancelled')),
    CHECK ((site_location_id IS NULL AND contact_id IS NULL) OR customer_party_id IS NOT NULL),
    CHECK (total_minor = subtotal_minor - discount_minor + tax_minor),
    FOREIGN KEY (customer_party_id, contact_id) REFERENCES party_contacts (party_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_party_id, site_location_id, site_party_location_id) REFERENCES party_locations (party_id, location_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (site_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_orders__number ON rental_orders (number);

-- rental_order_lines <- rental.rental_order_lines (server-only check 'qty'; server-only check 'target')
CREATE TABLE IF NOT EXISTS rental_order_lines (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT NOT NULL CHECK (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*'),
    line_no INTEGER NOT NULL,
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('rental', 'accessory', 'sale', 'fee', 'damage', 'overage', 'fuel', 'late', 'discount', 'adjustment', 'kit', 'labor', 'mobilization'))),
    class_id TEXT CHECK (class_id IS NULL OR (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*')),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    fee_id TEXT CHECK (fee_id IS NULL OR (length(fee_id) = 36 AND fee_id NOT GLOB '*[^0-9a-f-]*')),
    parent_line_id TEXT CHECK (parent_line_id IS NULL OR (length(parent_line_id) = 36 AND parent_line_id NOT GLOB '*[^0-9a-f-]*')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    description TEXT NOT NULL DEFAULT '',
    qty_micros INTEGER NOT NULL,
    start_at INTEGER,
    end_at INTEGER,
    actual_out_at INTEGER,
    actual_in_at INTEGER,
    rate_card_id TEXT CHECK (rate_card_id IS NULL OR (length(rate_card_id) = 36 AND rate_card_id NOT GLOB '*[^0-9a-f-]*')),
    price_snapshot TEXT CHECK (price_snapshot IS NULL OR (json_valid(price_snapshot))),
    unit_price_minor INTEGER,
    amount_minor INTEGER NOT NULL DEFAULT 0,
    discount_minor INTEGER NOT NULL DEFAULT 0,
    discount_bp INTEGER,
    taxable INTEGER NOT NULL DEFAULT 1 CHECK (taxable IN (0, 1)),
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    tax_snapshot TEXT NOT NULL CHECK (json_valid(tax_snapshot)),
    tax_minor INTEGER NOT NULL DEFAULT 0,
    price_overridden_by TEXT CHECK (price_overridden_by IS NULL OR (length(price_overridden_by) = 36 AND price_overridden_by NOT GLOB '*[^0-9a-f-]*')),
    override_reason TEXT,
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('open', 'out', 'returned', 'cancelled', 'swapped'))),
    invoiced_through INTEGER,
    stock_issued_at INTEGER,
    stock_movement_id TEXT CHECK (stock_movement_id IS NULL OR (length(stock_movement_id) = 36 AND stock_movement_id NOT GLOB '*[^0-9a-f-]*')),
    assign_unit_later INTEGER NOT NULL DEFAULT 0 CHECK (assign_unit_later IN (0, 1)),
    kit_id TEXT CHECK (kit_id IS NULL OR (length(kit_id) = 36 AND kit_id NOT GLOB '*[^0-9a-f-]*')),
    kit_component_id TEXT CHECK (kit_component_id IS NULL OR (length(kit_component_id) = 36 AND kit_component_id NOT GLOB '*[^0-9a-f-]*')),
    kit_instance_id TEXT CHECK (kit_instance_id IS NULL OR (length(kit_instance_id) = 36 AND kit_instance_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (start_at IS NULL OR end_at IS NULL OR start_at < end_at),
    CHECK (actual_out_at IS NULL OR actual_in_at IS NULL OR actual_out_at <= actual_in_at),
    CHECK (discount_bp IS NULL OR discount_bp BETWEEN 0 AND 10000),
    CHECK (price_overridden_by IS NULL OR override_reason IS NOT NULL),
    FOREIGN KEY (order_id, parent_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (stock_movement_id) REFERENCES stock_movements (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_order_lines__order_id_id ON rental_order_lines (order_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_rental_order_lines__order_id_line_no ON rental_order_lines (order_id, line_no);

-- rental_handovers <- rental.rental_handovers
CREATE TABLE IF NOT EXISTS rental_handovers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('checkout', 'checkin', 'readiness'))),
    at INTEGER NOT NULL,
    received_at INTEGER NOT NULL,
    by_user_id TEXT CHECK (by_user_id IS NULL OR (length(by_user_id) = 36 AND by_user_id NOT GLOB '*[^0-9a-f-]*')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    inspection_activity_id TEXT CHECK (inspection_activity_id IS NULL OR (length(inspection_activity_id) = 36 AND inspection_activity_id NOT GLOB '*[^0-9a-f-]*')),
    checkout_handover_id TEXT CHECK (checkout_handover_id IS NULL OR (length(checkout_handover_id) = 36 AND checkout_handover_id NOT GLOB '*[^0-9a-f-]*')),
    meter_reading_id TEXT CHECK (meter_reading_id IS NULL OR (length(meter_reading_id) = 36 AND meter_reading_id NOT GLOB '*[^0-9a-f-]*')),
    fuel_level_pct INTEGER,
    charge_level_pct INTEGER,
    accessories TEXT NOT NULL CHECK (json_valid(accessories)),
    damage_summary TEXT NOT NULL CHECK (json_valid(damage_summary)),
    charges TEXT NOT NULL CHECK (json_valid(charges)),
    customer_signature_id TEXT CHECK (customer_signature_id IS NULL OR (length(customer_signature_id) = 36 AND customer_signature_id NOT GLOB '*[^0-9a-f-]*')),
    staff_signature_id TEXT CHECK (staff_signature_id IS NULL OR (length(staff_signature_id) = 36 AND staff_signature_id NOT GLOB '*[^0-9a-f-]*')),
    notes TEXT,
    late_minutes INTEGER NOT NULL DEFAULT 0,
    voided_at INTEGER,
    voided_by TEXT CHECK (voided_by IS NULL OR (length(voided_by) = 36 AND voided_by NOT GLOB '*[^0-9a-f-]*')),
    void_reason TEXT,
    condition_code TEXT CHECK (condition_code IS NULL OR (length(condition_code) BETWEEN 1 AND 63 AND condition_code GLOB '[a-z]*' AND condition_code NOT GLOB '*[^a-z0-9_]*')),
    readiness_status TEXT CHECK (readiness_status IS NULL OR ((length(readiness_status) BETWEEN 1 AND 63 AND readiness_status GLOB '[a-z]*' AND readiness_status NOT GLOB '*[^a-z0-9_]*') AND (readiness_status IN ('pending', 'passed', 'failed', 'waived')))),
    readiness_items TEXT NOT NULL CHECK (json_valid(readiness_items)),
    PRIMARY KEY (id),
    CHECK ((kind = 'readiness') OR (order_id IS NOT NULL AND order_line_id IS NOT NULL)),
    CHECK ((kind = 'readiness') = (readiness_status IS NOT NULL)),
    CHECK (kind <> 'readiness' OR asset_id IS NOT NULL),
    CHECK ((fuel_level_pct IS NULL OR fuel_level_pct BETWEEN 0 AND 100) AND (charge_level_pct IS NULL OR charge_level_pct BETWEEN 0 AND 100)),
    CHECK (voided_at IS NULL OR coalesce(length(trim(void_reason)), 0) BETWEEN 1 AND 1000),
    FOREIGN KEY (order_id, order_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (inspection_activity_id) REFERENCES activity_records (id) ON DELETE RESTRICT,
    FOREIGN KEY (checkout_handover_id) REFERENCES rental_handovers (id) ON DELETE RESTRICT,
    FOREIGN KEY (meter_reading_id) REFERENCES meter_readings (id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_signature_id) REFERENCES signatures (id) ON DELETE SET NULL,
    FOREIGN KEY (staff_signature_id) REFERENCES signatures (id) ON DELETE SET NULL
) STRICT;

-- rental_bulk_returns <- rental.rental_bulk_returns (server-only check 'qty')
CREATE TABLE IF NOT EXISTS rental_bulk_returns (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    order_id TEXT NOT NULL CHECK (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*'),
    order_line_id TEXT NOT NULL CHECK (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*'),
    product_id TEXT NOT NULL CHECK (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    handover_id TEXT CHECK (handover_id IS NULL OR (length(handover_id) = 36 AND handover_id NOT GLOB '*[^0-9a-f-]*')),
    returned_at INTEGER NOT NULL,
    returned_qty_micros INTEGER NOT NULL,
    damaged_qty_micros INTEGER NOT NULL,
    lost_qty_micros INTEGER NOT NULL,
    final INTEGER NOT NULL DEFAULT 0 CHECK (final IN (0, 1)),
    charge_minor INTEGER NOT NULL DEFAULT 0,
    notes TEXT,
    recorded_by TEXT CHECK (recorded_by IS NULL OR (length(recorded_by) = 36 AND recorded_by NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    FOREIGN KEY (order_id, order_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (handover_id) REFERENCES rental_handovers (id) ON DELETE RESTRICT
) STRICT;

-- rental_delivery_tasks <- rental.rental_delivery_tasks (server-only check 'source')
CREATE TABLE IF NOT EXISTS rental_delivery_tasks (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('delivery', 'pickup', 'transfer', 'swap'))),
    status TEXT NOT NULL DEFAULT 'planned' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('planned', 'assigned', 'en_route', 'arrived', 'completed', 'failed', 'cancelled'))),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    transfer_id TEXT CHECK (transfer_id IS NULL OR (length(transfer_id) = 36 AND transfer_id NOT GLOB '*[^0-9a-f-]*')),
    destination_location_id TEXT CHECK (destination_location_id IS NULL OR (length(destination_location_id) = 36 AND destination_location_id NOT GLOB '*[^0-9a-f-]*')),
    destination_snapshot TEXT NOT NULL CHECK (json_valid(destination_snapshot)),
    contact_name TEXT,
    contact_phone TEXT,
    time_window_start INTEGER,
    time_window_end INTEGER,
    driver_user_id TEXT CHECK (driver_user_id IS NULL OR (length(driver_user_id) = 36 AND driver_user_id NOT GLOB '*[^0-9a-f-]*')),
    prev_driver_user_id TEXT CHECK (prev_driver_user_id IS NULL OR (length(prev_driver_user_id) = 36 AND prev_driver_user_id NOT GLOB '*[^0-9a-f-]*')),
    route_seq INTEGER,
    notes TEXT,
    started_at INTEGER,
    arrived_at INTEGER,
    completed_at INTEGER,
    failed_reason TEXT,
    proof_signature_id TEXT CHECK (proof_signature_id IS NULL OR (length(proof_signature_id) = 36 AND proof_signature_id NOT GLOB '*[^0-9a-f-]*')),
    proof_signed_name TEXT,
    proof_notes TEXT,
    proof_lat TEXT CHECK (proof_lat IS NULL OR (proof_lat NOT GLOB '*[^0-9.-]*' AND length(proof_lat) BETWEEN 1 AND 40)),
    proof_lng TEXT CHECK (proof_lng IS NULL OR (proof_lng NOT GLOB '*[^0-9.-]*' AND length(proof_lng) BETWEEN 1 AND 40)),
    auto_created INTEGER NOT NULL DEFAULT 0 CHECK (auto_created IN (0, 1)),
    route_id TEXT CHECK (route_id IS NULL OR (length(route_id) = 36 AND route_id NOT GLOB '*[^0-9a-f-]*')),
    route_locked INTEGER NOT NULL DEFAULT 0 CHECK (route_locked IN (0, 1)),
    service_minutes INTEGER,
    load_count INTEGER,
    load_weight_kg_micros INTEGER,
    eta_at INTEGER,
    eta_updated_at INTEGER,
    on_way_notified_at INTEGER,
    PRIMARY KEY (id),
    CHECK (status <> 'failed' OR failed_reason IS NOT NULL),
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (transfer_id) REFERENCES rental_transfers (id) ON DELETE RESTRICT,
    FOREIGN KEY (destination_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (proof_signature_id) REFERENCES signatures (id) ON DELETE SET NULL
) STRICT;

-- rental_transfers <- rental.rental_transfers
CREATE TABLE IF NOT EXISTS rental_transfers (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    asset_id TEXT NOT NULL CHECK (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*'),
    from_location_id TEXT CHECK (from_location_id IS NULL OR (length(from_location_id) = 36 AND from_location_id NOT GLOB '*[^0-9a-f-]*')),
    to_location_id TEXT NOT NULL CHECK (length(to_location_id) = 36 AND to_location_id NOT GLOB '*[^0-9a-f-]*'),
    status TEXT NOT NULL DEFAULT 'planned' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('planned', 'in_transit', 'received', 'cancelled'))),
    planned_during_start INTEGER NOT NULL,
    planned_during_end INTEGER,
    shipped_at INTEGER,
    received_at INTEGER,
    reason TEXT,
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    location_history_id TEXT CHECK (location_history_id IS NULL OR (length(location_history_id) = 36 AND location_history_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (from_location_id IS NULL OR from_location_id <> to_location_id),
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (from_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (to_location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT
) STRICT;

-- resource_allocations <- masters.resource_allocations (server-only check 'kind_target'; server-only check 'during'; server-only check 'one_source')
CREATE TABLE IF NOT EXISTS resource_allocations (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    during_start INTEGER NOT NULL,
    during_end INTEGER,
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    purpose TEXT NOT NULL CHECK ((length(purpose) BETWEEN 1 AND 63 AND purpose GLOB '[a-z]*' AND purpose NOT GLOB '*[^a-z0-9_]*') AND (purpose IN ('quote', 'hold', 'reserved', 'on_rent', 'buffer', 'maintenance', 'transfer', 'loan', 'coowner'))),
    expires_at INTEGER,
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    blocking INTEGER NOT NULL DEFAULT 1 CHECK (blocking IN (0, 1)),
    needs_review INTEGER NOT NULL DEFAULT 0 CHECK (needs_review IN (0, 1)),
    conflict INTEGER NOT NULL DEFAULT 0 CHECK (conflict IN (0, 1)),
    note TEXT,
    transfer_id TEXT CHECK (transfer_id IS NULL OR (length(transfer_id) = 36 AND transfer_id NOT GLOB '*[^0-9a-f-]*')),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    qty_micros INTEGER NOT NULL,
    class_id TEXT CHECK (class_id IS NULL OR (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*')),
    resource_kind TEXT NOT NULL CHECK ((length(resource_kind) BETWEEN 1 AND 63 AND resource_kind GLOB '[a-z]*' AND resource_kind NOT GLOB '*[^a-z0-9_]*') AND (resource_kind IN ('unit', 'class', 'bulk'))),
    loan_id TEXT CHECK (loan_id IS NULL OR (length(loan_id) = 36 AND loan_id NOT GLOB '*[^0-9a-f-]*')),
    coowner_booking_id TEXT CHECK (coowner_booking_id IS NULL OR (length(coowner_booking_id) = 36 AND coowner_booking_id NOT GLOB '*[^0-9a-f-]*')),
    buffer_of_id TEXT CHECK (buffer_of_id IS NULL OR (length(buffer_of_id) = 36 AND buffer_of_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (order_line_id IS NULL OR order_id IS NOT NULL),
    CHECK ((purpose IN ('quote', 'hold', 'reserved', 'on_rent') AND order_id IS NOT NULL) OR (purpose = 'loan' AND loan_id IS NOT NULL) OR (purpose = 'coowner' AND coowner_booking_id IS NOT NULL) OR (purpose = 'transfer' AND transfer_id IS NOT NULL) OR purpose IN ('buffer', 'maintenance')),
    CHECK ((purpose = 'buffer') = (buffer_of_id IS NOT NULL) OR (purpose = 'buffer' AND order_id IS NOT NULL)),
    FOREIGN KEY (order_id, order_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (transfer_id) REFERENCES rental_transfers (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE RESTRICT,
    FOREIGN KEY (buffer_of_id) REFERENCES resource_allocations (id) ON DELETE CASCADE
) STRICT;

-- signatures <- platform.signatures (server-only check 'subject')
CREATE TABLE IF NOT EXISTS signatures (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    document_id TEXT CHECK (document_id IS NULL OR (length(document_id) = 36 AND document_id NOT GLOB '*[^0-9a-f-]*')),
    signer_name TEXT NOT NULL,
    signer_email TEXT CHECK (signer_email IS NULL OR (signer_email = lower(trim(signer_email)) AND instr(signer_email, '@') > 1)),
    signer_role TEXT NOT NULL CHECK ((length(signer_role) BETWEEN 1 AND 63 AND signer_role GLOB '[a-z]*' AND signer_role NOT GLOB '*[^a-z0-9_]*') AND (signer_role IN ('customer', 'staff', 'driver', 'witness', 'permit_holder', 'approver'))),
    image_file_object_id TEXT CHECK (image_file_object_id IS NULL OR (length(image_file_object_id) = 36 AND image_file_object_id NOT GLOB '*[^0-9a-f-]*')),
    image_sha256 TEXT CHECK (image_sha256 IS NULL OR (length(image_sha256) = 64 AND image_sha256 NOT GLOB '*[^0-9a-f]*')),
    signed_at INTEGER NOT NULL,
    received_at INTEGER NOT NULL,
    ip TEXT,
    user_agent TEXT,
    device_id TEXT,
    geo_lat TEXT CHECK (geo_lat IS NULL OR (geo_lat NOT GLOB '*[^0-9.-]*' AND length(geo_lat) BETWEEN 1 AND 40)),
    geo_lng TEXT CHECK (geo_lng IS NULL OR (geo_lng NOT GLOB '*[^0-9.-]*' AND length(geo_lng) BETWEEN 1 AND 40)),
    method TEXT NOT NULL CHECK ((length(method) BETWEEN 1 AND 63 AND method GLOB '[a-z]*' AND method NOT GLOB '*[^a-z0-9_]*') AND (method IN ('in_person', 'remote'))),
    recorded_by TEXT CHECK (recorded_by IS NULL OR (length(recorded_by) = 36 AND recorded_by NOT GLOB '*[^0-9a-f-]*')),
    request_id TEXT CHECK (request_id IS NULL OR (length(request_id) = 36 AND request_id NOT GLOB '*[^0-9a-f-]*')),
    signer_id TEXT CHECK (signer_id IS NULL OR (length(signer_id) = 36 AND signer_id NOT GLOB '*[^0-9a-f-]*')),
    typed_name TEXT,
    consent_text_version TEXT,
    document_sha256 TEXT CHECK (document_sha256 IS NULL OR (length(document_sha256) = 64 AND document_sha256 NOT GLOB '*[^0-9a-f]*')),
    handover_id TEXT CHECK (handover_id IS NULL OR (length(handover_id) = 36 AND handover_id NOT GLOB '*[^0-9a-f-]*')),
    work_permit_id TEXT CHECK (work_permit_id IS NULL OR (length(work_permit_id) = 36 AND work_permit_id NOT GLOB '*[^0-9a-f-]*')),
    time_entry_id TEXT CHECK (time_entry_id IS NULL OR (length(time_entry_id) = 36 AND time_entry_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (signer_id IS NULL OR request_id IS NOT NULL),
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (image_file_object_id) REFERENCES files (id) ON DELETE RESTRICT,
    FOREIGN KEY (handover_id) REFERENCES rental_handovers (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_permit_id) REFERENCES work_permits (id) ON DELETE RESTRICT,
    FOREIGN KEY (time_entry_id) REFERENCES time_entries (id) ON DELETE RESTRICT
) STRICT;

-- invoices <- finance.invoices
CREATE TABLE IF NOT EXISTS invoices (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    customer_party_id TEXT NOT NULL CHECK (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*'),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    service_quote_id TEXT CHECK (service_quote_id IS NULL OR (length(service_quote_id) = 36 AND service_quote_id NOT GLOB '*[^0-9a-f-]*')),
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'sent', 'issued', 'partially_paid', 'paid', 'credited', 'void'))),
    notes TEXT,
    subtotal_minor INTEGER NOT NULL DEFAULT 0,
    tax_minor INTEGER NOT NULL DEFAULT 0,
    total_minor INTEGER NOT NULL DEFAULT 0,
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    due_on TEXT CHECK (due_on IS NULL OR (due_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
    sent_at INTEGER,
    buyer_snapshot TEXT CHECK (buyer_snapshot IS NULL OR (json_valid(buyer_snapshot))),
    service_period_start INTEGER,
    service_period_end INTEGER,
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL DEFAULT 'invoice' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('invoice', 'credit_note'))),
    credited_invoice_id TEXT CHECK (credited_invoice_id IS NULL OR (length(credited_invoice_id) = 36 AND credited_invoice_id NOT GLOB '*[^0-9a-f-]*')),
    series TEXT NOT NULL DEFAULT 'default' CHECK (length(series) BETWEEN 1 AND 63 AND series GLOB '[a-z]*' AND series NOT GLOB '*[^a-z0-9_]*'),
    seller_snapshot TEXT CHECK (seller_snapshot IS NULL OR (json_valid(seller_snapshot))),
    discount_minor INTEGER NOT NULL DEFAULT 0,
    paid_minor INTEGER NOT NULL DEFAULT 0,
    credited_minor INTEGER NOT NULL DEFAULT 0,
    tax_rounding TEXT DEFAULT 'per_line' CHECK (tax_rounding IS NULL OR ((length(tax_rounding) BETWEEN 1 AND 63 AND tax_rounding GLOB '[a-z]*' AND tax_rounding NOT GLOB '*[^a-z0-9_]*') AND (tax_rounding IN ('per_line', 'per_invoice')))),
    exemption_note TEXT,
    document_id TEXT CHECK (document_id IS NULL OR (length(document_id) = 36 AND document_id NOT GLOB '*[^0-9a-f-]*')),
    issued_at INTEGER,
    issued_by TEXT CHECK (issued_by IS NULL OR (length(issued_by) = 36 AND issued_by NOT GLOB '*[^0-9a-f-]*')),
    locale TEXT CHECK (locale IS NULL OR (length(locale) BETWEEN 2 AND 35)),
    void_reason TEXT,
    consolidated INTEGER NOT NULL DEFAULT 0 CHECK (consolidated IN (0, 1)),
    billing_cycle_id TEXT CHECK (billing_cycle_id IS NULL OR (length(billing_cycle_id) = 36 AND billing_cycle_id NOT GLOB '*[^0-9a-f-]*')),
    qbo_exported_at INTEGER,
    qbo_export_id TEXT CHECK (qbo_export_id IS NULL OR (length(qbo_export_id) = 36 AND qbo_export_id NOT GLOB '*[^0-9a-f-]*')),
    late_fee_for_invoice_id TEXT CHECK (late_fee_for_invoice_id IS NULL OR (length(late_fee_for_invoice_id) = 36 AND late_fee_for_invoice_id NOT GLOB '*[^0-9a-f-]*')),
    workflow TEXT NOT NULL DEFAULT 'rental' CHECK ((length(workflow) BETWEEN 1 AND 63 AND workflow GLOB '[a-z]*' AND workflow NOT GLOB '*[^a-z0-9_]*') AND (workflow IN ('rental', 'provider', 'legacy_period'))),
    voided_at INTEGER,
    voided_by TEXT CHECK (voided_by IS NULL OR (length(voided_by) = 36 AND voided_by NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK (status = 'draft' OR number IS NOT NULL),
    CHECK ((kind = 'credit_note') = (credited_invoice_id IS NOT NULL)),
    CHECK (subtotal_minor >= 0 AND tax_minor >= 0 AND discount_minor >= 0 AND total_minor >= 0 AND paid_minor >= 0 AND credited_minor >= 0),
    CHECK (paid_minor + credited_minor <= total_minor),
    CHECK ((status = 'void') = (voided_at IS NOT NULL) AND (status <> 'void' OR (coalesce(length(trim(void_reason)), 0) BETWEEN 1 AND 1000 AND paid_minor = 0 AND credited_minor = 0))),
    CHECK (status = 'draft' OR issued_at IS NOT NULL),
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (credited_invoice_id) REFERENCES invoices (id) ON DELETE RESTRICT,
    FOREIGN KEY (late_fee_for_invoice_id) REFERENCES invoices (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoices__series_number ON invoices (series, number) WHERE number IS NOT NULL;

-- invoice_lines <- finance.invoice_lines
CREATE TABLE IF NOT EXISTS invoice_lines (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    invoice_id TEXT NOT NULL CHECK (length(invoice_id) = 36 AND invoice_id NOT GLOB '*[^0-9a-f-]*'),
    line_no INTEGER NOT NULL CHECK (line_no >= 1),
    kind TEXT NOT NULL DEFAULT 'item' CHECK (length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*'),
    description TEXT NOT NULL,
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    qty_micros INTEGER NOT NULL,
    unit TEXT CHECK (unit IS NULL OR (length(unit) BETWEEN 1 AND 63 AND unit GLOB '[a-z]*' AND unit NOT GLOB '*[^a-z0-9_]*')),
    unit_price TEXT NOT NULL CHECK (unit_price NOT GLOB '*[^0-9.-]*' AND length(unit_price) BETWEEN 1 AND 40),
    discount_minor INTEGER NOT NULL DEFAULT 0,
    amount_minor INTEGER NOT NULL,
    tax_minor INTEGER NOT NULL DEFAULT 0,
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    tax_snapshot TEXT NOT NULL CHECK (json_valid(tax_snapshot)),
    service_period_start INTEGER,
    service_period_end INTEGER,
    PRIMARY KEY (id),
    CHECK (order_line_id IS NULL OR order_id IS NOT NULL),
    FOREIGN KEY (order_id, order_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoice_lines__invoice_id_id ON invoice_lines (invoice_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoice_lines__invoice_id_line_no ON invoice_lines (invoice_id, line_no);

-- customer_balances <- finance.customer_balances
CREATE TABLE IF NOT EXISTS customer_balances (
    created_at INTEGER NOT NULL,
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    party_id TEXT NOT NULL CHECK (length(party_id) = 36 AND party_id NOT GLOB '*[^0-9a-f-]*'),
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    receivable_minor INTEGER NOT NULL DEFAULT 0,
    unapplied_credit_minor INTEGER NOT NULL DEFAULT 0,
    deposit_liability_minor INTEGER NOT NULL DEFAULT 0,
    pending_authorization_minor INTEGER NOT NULL DEFAULT 0,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (party_id, currency),
    FOREIGN KEY (party_id) REFERENCES parties (id) ON DELETE CASCADE
) STRICT;

-- ================================================= area specialist

-- listing_profiles <- commerce.listing_profiles
CREATE TABLE IF NOT EXISTS listing_profiles (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    class_id TEXT NOT NULL CHECK (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*'),
    marketplace_listed INTEGER NOT NULL DEFAULT 1 CHECK (marketplace_listed IN (0, 1)),
    marketplace_category TEXT CHECK (marketplace_category IS NULL OR (length(marketplace_category) BETWEEN 1 AND 63 AND marketplace_category GLOB '[a-z]*' AND marketplace_category NOT GLOB '*[^a-z0-9_]*')),
    summary TEXT NOT NULL CHECK (json_valid(summary) AND json_type(summary) = 'object'),
    offer_pickup INTEGER CHECK (offer_pickup IS NULL OR (offer_pickup IN (0, 1))),
    offer_delivery INTEGER CHECK (offer_delivery IS NULL OR (offer_delivery IN (0, 1))),
    offer_meetup INTEGER CHECK (offer_meetup IS NULL OR (offer_meetup IN (0, 1))),
    search_enabled INTEGER NOT NULL DEFAULT 0 CHECK (search_enabled IN (0, 1)),
    search_category_slug TEXT,
    delivery_available INTEGER NOT NULL DEFAULT 0 CHECK (delivery_available IN (0, 1)),
    search_suspended INTEGER NOT NULL DEFAULT 0 CHECK (search_suspended IN (0, 1)),
    search_suspended_reason TEXT CHECK (search_suspended_reason IS NULL OR (length(search_suspended_reason) <= 1000)),
    projection_dirty_at INTEGER,
    PRIMARY KEY (class_id),
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE CASCADE
) STRICT;

-- listing_profile_photos <- commerce.listing_profile_photos
CREATE TABLE IF NOT EXISTS listing_profile_photos (
    created_at INTEGER NOT NULL,
    class_id TEXT NOT NULL CHECK (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*'),
    ordinal INTEGER NOT NULL CHECK (ordinal BETWEEN 0 AND 49),
    file_id TEXT NOT NULL CHECK (length(file_id) = 36 AND file_id NOT GLOB '*[^0-9a-f-]*'),
    PRIMARY KEY (class_id, ordinal),
    FOREIGN KEY (class_id) REFERENCES listing_profiles (class_id) ON DELETE CASCADE,
    FOREIGN KEY (file_id) REFERENCES files (id) ON DELETE RESTRICT
) STRICT, WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_listing_profile_photos__class_id_file_id ON listing_profile_photos (class_id, file_id);

-- storefronts <- commerce.storefronts (per-account singleton)
CREATE TABLE IF NOT EXISTS storefronts (
    singleton INTEGER NOT NULL DEFAULT 1 PRIMARY KEY CHECK (singleton = 1),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    slug TEXT NOT NULL CHECK (length(slug) BETWEEN 3 AND 63),
    enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    portal_enabled INTEGER NOT NULL DEFAULT 1 CHECK (portal_enabled IN (0, 1)),
    title TEXT CHECK (title IS NULL OR (length(title) <= 200)),
    intro TEXT NOT NULL CHECK (json_valid(intro) AND json_type(intro) = 'object'),
    contact_email TEXT CHECK (contact_email IS NULL OR (contact_email = lower(trim(contact_email)) AND instr(contact_email, '@') > 1)),
    contact_phone TEXT CHECK (contact_phone IS NULL OR (length(contact_phone) <= 50)),
    booking_mode TEXT NOT NULL DEFAULT 'hold' CHECK ((length(booking_mode) BETWEEN 1 AND 63 AND booking_mode GLOB '[a-z]*' AND booking_mode NOT GLOB '*[^a-z0-9_]*') AND (booking_mode IN ('hold', 'quote'))),
    show_prices INTEGER NOT NULL DEFAULT 1 CHECK (show_prices IN (0, 1)),
    min_lead_minutes INTEGER NOT NULL DEFAULT 60 CHECK (min_lead_minutes >= 0),
    max_days INTEGER NOT NULL DEFAULT 365 CHECK (max_days BETWEEN 1 AND 3650)
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_storefronts__slug ON storefronts (slug);

-- storefront_locations <- commerce.storefront_locations
CREATE TABLE IF NOT EXISTS storefront_locations (
    created_at INTEGER NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    location_id TEXT NOT NULL CHECK (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*'),
    PRIMARY KEY (ordinal),
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_storefront_locations__location_id ON storefront_locations (location_id);

-- meetup_requests <- commerce.meetup_requests
CREATE TABLE IF NOT EXISTS meetup_requests (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    renter_id TEXT NOT NULL CHECK (length(renter_id) = 36 AND renter_id NOT GLOB '*[^0-9a-f-]*'),
    class_id TEXT NOT NULL CHECK (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*'),
    location_id TEXT CHECK (location_id IS NULL OR (length(location_id) = 36 AND location_id NOT GLOB '*[^0-9a-f-]*')),
    qty INTEGER NOT NULL DEFAULT 1 CHECK (qty BETWEEN 1 AND 20),
    status TEXT NOT NULL DEFAULT 'pending' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('pending', 'countered', 'accepted', 'declined', 'cancelled', 'expired'))),
    proposed_slots TEXT NOT NULL CHECK ((json_valid(proposed_slots)) AND (json_type(proposed_slots) = 'array')),
    counter_start INTEGER,
    counter_end INTEGER,
    accepted_start INTEGER,
    accepted_end INTEGER,
    rental_start INTEGER,
    rental_end INTEGER,
    message TEXT CHECK (message IS NULL OR (length(message) <= 2000)),
    owner_message TEXT CHECK (owner_message IS NULL OR (length(owner_message) <= 2000)),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    responded_by TEXT CHECK (responded_by IS NULL OR (length(responded_by) = 36 AND responded_by NOT GLOB '*[^0-9a-f-]*')),
    responded_at INTEGER,
    expires_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    CHECK (rental_end IS NULL OR rental_start IS NULL OR rental_end > rental_start),
    CHECK (counter_end IS NULL OR counter_start IS NULL OR counter_end > counter_start),
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE CASCADE,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE SET NULL,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE SET NULL,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE SET NULL
) STRICT;

-- change_requests <- commerce.change_requests
CREATE TABLE IF NOT EXISTS change_requests (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    renter_id TEXT NOT NULL CHECK (length(renter_id) = 36 AND renter_id NOT GLOB '*[^0-9a-f-]*'),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('meetup_time', 'booking_dates', 'booking_cancel'))),
    meetup_id TEXT CHECK (meetup_id IS NULL OR (length(meetup_id) = 36 AND meetup_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    proposed_slots TEXT CHECK (proposed_slots IS NULL OR (json_valid(proposed_slots))),
    start_at INTEGER,
    end_at INTEGER,
    prev_start_at INTEGER,
    prev_end_at INTEGER,
    message TEXT CHECK (message IS NULL OR (length(message) <= 2000)),
    owner_message TEXT CHECK (owner_message IS NULL OR (length(owner_message) <= 2000)),
    status TEXT NOT NULL DEFAULT 'pending' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('pending', 'accepted', 'declined', 'withdrawn', 'superseded'))),
    responded_by TEXT CHECK (responded_by IS NULL OR (length(responded_by) = 36 AND responded_by NOT GLOB '*[^0-9a-f-]*')),
    responded_at INTEGER,
    PRIMARY KEY (id),
    CHECK (kind <> 'booking_dates' OR (start_at IS NOT NULL AND end_at IS NOT NULL AND end_at > start_at)),
    CHECK (kind <> 'meetup_time' OR proposed_slots IS NOT NULL),
    CHECK ((kind = 'meetup_time') <> (order_id IS NOT NULL)),
    CHECK ((kind = 'meetup_time') = (meetup_id IS NOT NULL)),
    FOREIGN KEY (meetup_id) REFERENCES meetup_requests (id) ON DELETE CASCADE,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE SET NULL
) STRICT;

-- instant_book_rules <- commerce.instant_book_rules
CREATE TABLE IF NOT EXISTS instant_book_rules (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    class_id TEXT CHECK (class_id IS NULL OR (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    min_lead_minutes INTEGER NOT NULL DEFAULT 0 CHECK (min_lead_minutes BETWEEN 0 AND 525600),
    max_duration_minutes INTEGER CHECK (max_duration_minutes IS NULL OR (max_duration_minutes > 0)),
    require_verified_renter INTEGER NOT NULL DEFAULT 0 CHECK (require_verified_renter IN (0, 1)),
    require_verified_licence INTEGER NOT NULL DEFAULT 0 CHECK (require_verified_licence IN (0, 1)),
    min_rating TEXT CHECK (min_rating IS NULL OR ((min_rating NOT GLOB '*[^0-9.-]*' AND length(min_rating) BETWEEN 1 AND 40) AND (min_rating BETWEEN 0 AND 5))),
    repeat_renters_only INTEGER NOT NULL DEFAULT 0 CHECK (repeat_renters_only IN (0, 1)),
    buffer_minutes INTEGER NOT NULL DEFAULT 0 CHECK (buffer_minutes BETWEEN 0 AND 10080),
    delivery_allowed INTEGER NOT NULL DEFAULT 1 CHECK (delivery_allowed IN (0, 1)),
    PRIMARY KEY (id),
    CHECK (class_id IS NULL OR asset_id IS NULL),
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE
) STRICT;

-- reviews <- commerce.reviews
CREATE TABLE IF NOT EXISTS reviews (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    order_id TEXT NOT NULL CHECK (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*'),
    direction TEXT NOT NULL CHECK ((length(direction) BETWEEN 1 AND 63 AND direction GLOB '[a-z]*' AND direction NOT GLOB '*[^a-z0-9_]*') AND (direction IN ('renter_to_owner', 'owner_to_renter'))),
    customer_party_id TEXT NOT NULL CHECK (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*'),
    renter_id TEXT CHECK (renter_id IS NULL OR (length(renter_id) = 36 AND renter_id NOT GLOB '*[^0-9a-f-]*')),
    author_user_id TEXT CHECK (author_user_id IS NULL OR (length(author_user_id) = 36 AND author_user_id NOT GLOB '*[^0-9a-f-]*')),
    item_condition INTEGER CHECK (item_condition IS NULL OR (item_condition BETWEEN 1 AND 5)),
    listing_accuracy INTEGER CHECK (listing_accuracy IS NULL OR (listing_accuracy BETWEEN 1 AND 5)),
    owner_communication INTEGER CHECK (owner_communication IS NULL OR (owner_communication BETWEEN 1 AND 5)),
    handover_delivery INTEGER CHECK (handover_delivery IS NULL OR (handover_delivery BETWEEN 1 AND 5)),
    on_time INTEGER CHECK (on_time IS NULL OR (on_time BETWEEN 1 AND 5)),
    care INTEGER CHECK (care IS NULL OR (care BETWEEN 1 AND 5)),
    communication INTEGER CHECK (communication IS NULL OR (communication BETWEEN 1 AND 5)),
    body TEXT CHECK (body IS NULL OR (length(body) <= 4000)),
    status TEXT NOT NULL DEFAULT 'submitted' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('submitted', 'published', 'held', 'removed', 'cancelled_fraud'))),
    submitted_at INTEGER NOT NULL,
    revealed_at INTEGER,
    owner_reply TEXT CHECK (owner_reply IS NULL OR (length(owner_reply) <= 2000)),
    owner_reply_at INTEGER,
    owner_reply_by TEXT CHECK (owner_reply_by IS NULL OR (length(owner_reply_by) = 36 AND owner_reply_by NOT GLOB '*[^0-9a-f-]*')),
    reported_reason TEXT CHECK (reported_reason IS NULL OR (length(reported_reason) BETWEEN 1 AND 63 AND reported_reason GLOB '[a-z]*' AND reported_reason NOT GLOB '*[^a-z0-9_]*')),
    reported_note TEXT CHECK (reported_note IS NULL OR (length(reported_note) <= 2000)),
    reported_at INTEGER,
    removal_reason_code TEXT CHECK (removal_reason_code IS NULL OR ((length(removal_reason_code) BETWEEN 1 AND 63 AND removal_reason_code GLOB '[a-z]*' AND removal_reason_code NOT GLOB '*[^a-z0-9_]*') AND (removal_reason_code IN ('personal_data', 'hate_speech', 'threat', 'unrelated', 'proven_fraud')))),
    removal_note TEXT CHECK (removal_note IS NULL OR (length(removal_note) <= 2000)),
    removed_at INTEGER,
    removed_by TEXT CHECK (removed_by IS NULL OR (length(removed_by) = 36 AND removed_by NOT GLOB '*[^0-9a-f-]*')),
    appeal_status TEXT CHECK (appeal_status IS NULL OR ((length(appeal_status) BETWEEN 1 AND 63 AND appeal_status GLOB '[a-z]*' AND appeal_status NOT GLOB '*[^a-z0-9_]*') AND (appeal_status IN ('pending', 'upheld', 'reinstated')))),
    appeal_note TEXT CHECK (appeal_note IS NULL OR (length(appeal_note) <= 2000)),
    appealed_at INTEGER,
    appeal_decided_at INTEGER,
    PRIMARY KEY (id),
    CHECK ((status = 'removed') <= (removal_reason_code IS NOT NULL)),
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_reviews__order_id_direction ON reviews (order_id, direction);

-- review_subjects <- commerce.review_subjects
CREATE TABLE IF NOT EXISTS review_subjects (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    review_id TEXT NOT NULL CHECK (length(review_id) = 36 AND review_id NOT GLOB '*[^0-9a-f-]*'),
    subject_kind TEXT NOT NULL CHECK ((length(subject_kind) BETWEEN 1 AND 63 AND subject_kind GLOB '[a-z]*' AND subject_kind NOT GLOB '*[^a-z0-9_]*') AND (subject_kind IN ('asset', 'class', 'category'))),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    class_id TEXT CHECK (class_id IS NULL OR (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*')),
    category_id TEXT CHECK (category_id IS NULL OR (length(category_id) = 36 AND category_id NOT GLOB '*[^0-9a-f-]*')),
    PRIMARY KEY (id),
    CHECK ((subject_kind = 'asset' AND asset_id IS NOT NULL AND class_id IS NULL AND category_id IS NULL) OR (subject_kind = 'class' AND class_id IS NOT NULL AND asset_id IS NULL AND category_id IS NULL) OR (subject_kind = 'category' AND category_id IS NOT NULL AND asset_id IS NULL AND class_id IS NULL)),
    FOREIGN KEY (review_id) REFERENCES reviews (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE CASCADE,
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

-- review_photos <- commerce.review_photos
CREATE TABLE IF NOT EXISTS review_photos (
    created_at INTEGER NOT NULL,
    review_id TEXT NOT NULL CHECK (length(review_id) = 36 AND review_id NOT GLOB '*[^0-9a-f-]*'),
    ordinal INTEGER NOT NULL CHECK (ordinal BETWEEN 0 AND 19),
    file_id TEXT CHECK (file_id IS NULL OR (length(file_id) = 36 AND file_id NOT GLOB '*[^0-9a-f-]*')),
    url TEXT CHECK (url IS NULL OR (url LIKE 'https://%')),
    caption TEXT CHECK (caption IS NULL OR (length(caption) <= 500)),
    PRIMARY KEY (review_id, ordinal),
    CHECK (file_id IS NOT NULL OR url IS NOT NULL),
    FOREIGN KEY (review_id) REFERENCES reviews (id) ON DELETE CASCADE,
    FOREIGN KEY (file_id) REFERENCES files (id) ON DELETE SET NULL
) STRICT, WITHOUT ROWID;

-- trust_cases <- commerce.trust_cases
CREATE TABLE IF NOT EXISTS trust_cases (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    case_number INTEGER NOT NULL CHECK (case_number > 0),
    case_type TEXT NOT NULL CHECK ((length(case_type) BETWEEN 1 AND 63 AND case_type GLOB '[a-z]*' AND case_type NOT GLOB '*[^a-z0-9_]*') AND (case_type IN ('damage', 'dispute', 'safety', 'no_show', 'late_return', 'listing_inaccuracy', 'fraud'))),
    severity TEXT NOT NULL DEFAULT 'standard' CHECK ((length(severity) BETWEEN 1 AND 63 AND severity GLOB '[a-z]*' AND severity NOT GLOB '*[^a-z0-9_]*') AND (severity IN ('low', 'standard', 'critical'))),
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('open', 'awaiting_owner', 'awaiting_renter', 'escalated', 'resolved', 'closed'))),
    opened_by TEXT NOT NULL CHECK ((length(opened_by) BETWEEN 1 AND 63 AND opened_by GLOB '[a-z]*' AND opened_by NOT GLOB '*[^a-z0-9_]*') AND (opened_by IN ('renter', 'owner', 'admin', 'system'))),
    opened_by_user_id TEXT CHECK (opened_by_user_id IS NULL OR (length(opened_by_user_id) = 36 AND opened_by_user_id NOT GLOB '*[^0-9a-f-]*')),
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    renter_id TEXT CHECK (renter_id IS NULL OR (length(renter_id) = 36 AND renter_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    class_id TEXT CHECK (class_id IS NULL OR (length(class_id) = 36 AND class_id NOT GLOB '*[^0-9a-f-]*')),
    subject TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 200),
    description TEXT CHECK (description IS NULL OR (length(description) <= 8000)),
    first_response_due INTEGER NOT NULL,
    escalate_at INTEGER NOT NULL,
    resolve_due INTEGER NOT NULL,
    first_response_at INTEGER,
    escalated_at INTEGER,
    resolved_at INTEGER,
    closed_at INTEGER,
    outcome_code TEXT CHECK (outcome_code IS NULL OR (length(outcome_code) BETWEEN 1 AND 63 AND outcome_code GLOB '[a-z]*' AND outcome_code NOT GLOB '*[^a-z0-9_]*')),
    outcome_note TEXT CHECK (outcome_note IS NULL OR (length(outcome_note) <= 8000)),
    money_actions TEXT NOT NULL CHECK ((json_valid(money_actions)) AND (json_type(money_actions) = 'array')),
    provider_dispute_id TEXT,
    ledger_entry_id TEXT CHECK (ledger_entry_id IS NULL OR (length(ledger_entry_id) = 36 AND ledger_entry_id NOT GLOB '*[^0-9a-f-]*')),
    work_order_id TEXT CHECK (work_order_id IS NULL OR (length(work_order_id) = 36 AND work_order_id NOT GLOB '*[^0-9a-f-]*')),
    defect_id TEXT CHECK (defect_id IS NULL OR (length(defect_id) = 36 AND defect_id NOT GLOB '*[^0-9a-f-]*')),
    listing_action TEXT CHECK (listing_action IS NULL OR ((length(listing_action) BETWEEN 1 AND 63 AND listing_action GLOB '[a-z]*' AND listing_action NOT GLOB '*[^a-z0-9_]*') AND (listing_action IN ('paused', 'suspended')))),
    legal_hold INTEGER NOT NULL DEFAULT 0 CHECK (legal_hold IN (0, 1)),
    PRIMARY KEY (id),
    CHECK (first_response_due <= resolve_due),
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE SET NULL,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE SET NULL,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE SET NULL,
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE SET NULL,
    FOREIGN KEY (work_order_id) REFERENCES work_orders (id) ON DELETE SET NULL,
    FOREIGN KEY (defect_id) REFERENCES inspection_defects (id) ON DELETE SET NULL
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_trust_cases__case_number ON trust_cases (case_number);

-- trust_case_events <- commerce.trust_case_events
CREATE TABLE IF NOT EXISTS trust_case_events (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    case_id TEXT NOT NULL CHECK (length(case_id) = 36 AND case_id NOT GLOB '*[^0-9a-f-]*'),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('opened', 'message', 'evidence', 'status', 'outcome', 'escalated', 'listing', 'appeal'))),
    actor TEXT NOT NULL CHECK ((length(actor) BETWEEN 1 AND 63 AND actor GLOB '[a-z]*' AND actor NOT GLOB '*[^a-z0-9_]*') AND (actor IN ('renter', 'owner', 'admin', 'system'))),
    actor_user_id TEXT CHECK (actor_user_id IS NULL OR (length(actor_user_id) = 36 AND actor_user_id NOT GLOB '*[^0-9a-f-]*')),
    visibility TEXT NOT NULL DEFAULT 'both' CHECK ((length(visibility) BETWEEN 1 AND 63 AND visibility GLOB '[a-z]*' AND visibility NOT GLOB '*[^a-z0-9_]*') AND (visibility IN ('internal', 'owner', 'renter', 'both'))),
    body TEXT CHECK (body IS NULL OR (length(body) <= 8000)),
    handover_id TEXT CHECK (handover_id IS NULL OR (length(handover_id) = 36 AND handover_id NOT GLOB '*[^0-9a-f-]*')),
    activity_record_id TEXT CHECK (activity_record_id IS NULL OR (length(activity_record_id) = 36 AND activity_record_id NOT GLOB '*[^0-9a-f-]*')),
    photos TEXT NOT NULL CHECK (json_valid(photos)),
    data TEXT NOT NULL CHECK (json_valid(data)),
    PRIMARY KEY (id),
    FOREIGN KEY (case_id) REFERENCES trust_cases (id) ON DELETE CASCADE,
    FOREIGN KEY (handover_id) REFERENCES rental_handovers (id) ON DELETE SET NULL,
    FOREIGN KEY (activity_record_id) REFERENCES activity_records (id) ON DELETE SET NULL
) STRICT;

-- notifications <- platform.notifications
CREATE TABLE IF NOT EXISTS notifications (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL DEFAULT 'alert' CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('alert', 'sync_invalidation'))),
    event_key TEXT CHECK (event_key IS NULL OR (length(event_key) BETWEEN 1 AND 80)),
    target_user_id TEXT CHECK (target_user_id IS NULL OR (length(target_user_id) = 36 AND target_user_id NOT GLOB '*[^0-9a-f-]*')),
    exclude_device_id TEXT CHECK (exclude_device_id IS NULL OR (length(exclude_device_id) = 36 AND exclude_device_id NOT GLOB '*[^0-9a-f-]*')),
    entity_type TEXT CHECK (entity_type IS NULL OR (length(entity_type) BETWEEN 1 AND 63 AND entity_type GLOB '[a-z]*' AND entity_type NOT GLOB '*[^a-z0-9_]*')),
    entity_id TEXT CHECK (entity_id IS NULL OR (length(entity_id) = 36 AND entity_id NOT GLOB '*[^0-9a-f-]*')),
    title TEXT CHECK (title IS NULL OR (length(title) <= 500)),
    body TEXT CHECK (body IS NULL OR (length(body) <= 4000)),
    data TEXT NOT NULL CHECK (json_valid(data)),
    avatar_url TEXT,
    image_thumb_url TEXT,
    deep_link TEXT,
    chat_thread_id TEXT CHECK (chat_thread_id IS NULL OR (length(chat_thread_id) = 36 AND chat_thread_id NOT GLOB '*[^0-9a-f-]*')),
    chat_message_id TEXT CHECK (chat_message_id IS NULL OR (length(chat_message_id) = 36 AND chat_message_id NOT GLOB '*[^0-9a-f-]*')),
    quiet_hours_respected INTEGER NOT NULL DEFAULT 1 CHECK (quiet_hours_respected IN (0, 1)),
    status TEXT NOT NULL DEFAULT 'pending' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('pending', 'sent', 'failed', 'skipped'))),
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    recipient_count INTEGER NOT NULL DEFAULT 0 CHECK (recipient_count >= 0),
    dedupe_key TEXT CHECK (dedupe_key IS NULL OR (length(dedupe_key) <= 200)),
    sent_at INTEGER,
    PRIMARY KEY (id)
) STRICT;

-- notification_preferences <- platform.notification_preferences
CREATE TABLE IF NOT EXISTS notification_preferences (
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    event_key TEXT NOT NULL CHECK (length(event_key) BETWEEN 1 AND 80),
    channel TEXT NOT NULL CHECK ((length(channel) BETWEEN 1 AND 63 AND channel GLOB '[a-z]*' AND channel NOT GLOB '*[^a-z0-9_]*') AND (channel IN ('push', 'email'))),
    enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    PRIMARY KEY (user_id, event_key, channel)
) STRICT;

-- saved_views <- platform.saved_views
CREATE TABLE IF NOT EXISTS saved_views (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    owner_user_id TEXT NOT NULL CHECK (length(owner_user_id) = 36 AND owner_user_id NOT GLOB '*[^0-9a-f-]*'),
    dataset TEXT NOT NULL CHECK (length(dataset) BETWEEN 1 AND 63 AND dataset GLOB '[a-z]*' AND dataset NOT GLOB '*[^a-z0-9_]*'),
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    spec TEXT NOT NULL CHECK (json_valid(spec)),
    visibility TEXT NOT NULL DEFAULT 'private' CHECK ((length(visibility) BETWEEN 1 AND 63 AND visibility GLOB '[a-z]*' AND visibility NOT GLOB '*[^a-z0-9_]*') AND (visibility IN ('private', 'account'))),
    PRIMARY KEY (id)
) STRICT;

-- ================================================= area sync

-- sync_conflicts <- platform.sync_conflicts
CREATE TABLE IF NOT EXISTS sync_conflicts (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    command_id TEXT NOT NULL CHECK (length(command_id) = 36 AND command_id NOT GLOB '*[^0-9a-f-]*'),
    actor_user_id TEXT NOT NULL CHECK (length(actor_user_id) = 36 AND actor_user_id NOT GLOB '*[^0-9a-f-]*'),
    entity_type TEXT NOT NULL CHECK (length(entity_type) BETWEEN 1 AND 63 AND entity_type GLOB '[a-z]*' AND entity_type NOT GLOB '*[^a-z0-9_]*'),
    entity_key TEXT NOT NULL CHECK (length(entity_key) BETWEEN 1 AND 400),
    base_version INTEGER,
    server_version INTEGER,
    client_payload TEXT NOT NULL CHECK (json_valid(client_payload)),
    server_snapshot TEXT CHECK (server_snapshot IS NULL OR (json_valid(server_snapshot))),
    status TEXT NOT NULL DEFAULT 'open' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('open', 'resolved_client', 'resolved_server', 'dismissed'))),
    resolved_by_user_id TEXT CHECK (resolved_by_user_id IS NULL OR (length(resolved_by_user_id) = 36 AND resolved_by_user_id NOT GLOB '*[^0-9a-f-]*')),
    resolved_at INTEGER,
    PRIMARY KEY (id),
    CHECK ((status = 'open') = (resolved_at IS NULL))
) STRICT;
CREATE INDEX IF NOT EXISTS ix_sync_conflicts__status_created_at ON sync_conflicts (status, created_at);

-- database_identity <- projection-only
CREATE TABLE IF NOT EXISTS database_identity (
    singleton INTEGER NOT NULL DEFAULT 1 CHECK (singleton = 1),
    format TEXT NOT NULL DEFAULT 'avago-v2' CHECK (format = 'avago-v2'),
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    account_id TEXT NOT NULL CHECK (length(account_id) = 36 AND account_id NOT GLOB '*[^0-9a-f-]*'),
    device_id TEXT NOT NULL CHECK (length(device_id) = 36 AND device_id NOT GLOB '*[^0-9a-f-]*'),
    contract_version INTEGER NOT NULL,
    scope_epoch INTEGER NOT NULL,
    feed_generation INTEGER NOT NULL,
    global_feed_generation INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    auth_lease_expires_at INTEGER,
    PRIMARY KEY (singleton)
) STRICT;

-- sync_state <- projection-only
CREATE TABLE IF NOT EXISTS sync_state (
    stream TEXT NOT NULL CHECK ((length(stream) BETWEEN 1 AND 63 AND stream GLOB '[a-z]*' AND stream NOT GLOB '*[^a-z0-9_]*') AND (stream IN ('account', 'global'))),
    cursor INTEGER NOT NULL DEFAULT 0 CHECK (cursor >= 0),
    feed_generation INTEGER NOT NULL DEFAULT 1,
    last_session_id TEXT CHECK (last_session_id IS NULL OR (length(last_session_id) = 36 AND last_session_id NOT GLOB '*[^0-9a-f-]*')),
    last_applied_at INTEGER,
    bootstrap_state TEXT NOT NULL DEFAULT 'none' CHECK ((length(bootstrap_state) BETWEEN 1 AND 63 AND bootstrap_state GLOB '[a-z]*' AND bootstrap_state NOT GLOB '*[^a-z0-9_]*') AND (bootstrap_state IN ('none', 'in_progress', 'complete'))),
    status TEXT NOT NULL DEFAULT 'ok' CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('ok', 'bootstrap_required', 'scope_changed', 'upgrade_required'))),
    PRIMARY KEY (stream)
) STRICT;

-- sync_staging <- projection-only
CREATE TABLE IF NOT EXISTS sync_staging (
    session_id TEXT NOT NULL CHECK (length(session_id) = 36 AND session_id NOT GLOB '*[^0-9a-f-]*'),
    stream TEXT NOT NULL CHECK ((length(stream) BETWEEN 1 AND 63 AND stream GLOB '[a-z]*' AND stream NOT GLOB '*[^a-z0-9_]*') AND (stream IN ('account', 'global'))),
    page_no INTEGER NOT NULL CHECK (page_no >= 0),
    session_token TEXT NOT NULL,
    w INTEGER NOT NULL,
    g INTEGER NOT NULL,
    after_seq INTEGER NOT NULL CHECK (after_seq >= 0),
    last_seq INTEGER NOT NULL,
    item_count INTEGER NOT NULL CHECK (item_count >= 0),
    checksum TEXT NOT NULL CHECK (length(checksum) = 64 AND checksum NOT GLOB '*[^0-9a-f]*'),
    payload BLOB NOT NULL,
    is_final INTEGER NOT NULL DEFAULT 0 CHECK (is_final IN (0, 1)),
    received_at INTEGER NOT NULL,
    PRIMARY KEY (session_id, stream, page_no)
) STRICT, WITHOUT ROWID;

-- pending_commands <- projection-only
CREATE TABLE IF NOT EXISTS pending_commands (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    user_id TEXT NOT NULL CHECK (length(user_id) = 36 AND user_id NOT GLOB '*[^0-9a-f-]*'),
    account_id TEXT NOT NULL CHECK (length(account_id) = 36 AND account_id NOT GLOB '*[^0-9a-f-]*'),
    scope_epoch INTEGER NOT NULL,
    operation TEXT NOT NULL,
    payload_schema_version INTEGER NOT NULL DEFAULT 1,
    entity_type TEXT CHECK (entity_type IS NULL OR (length(entity_type) BETWEEN 1 AND 63 AND entity_type GLOB '[a-z]*' AND entity_type NOT GLOB '*[^a-z0-9_]*')),
    entity_key TEXT,
    base_version INTEGER,
    payload TEXT NOT NULL,
    request_hash TEXT NOT NULL CHECK (length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'),
    causal_order INTEGER NOT NULL,
    state TEXT NOT NULL DEFAULT 'queued' CHECK ((length(state) BETWEEN 1 AND 63 AND state GLOB '[a-z]*' AND state NOT GLOB '*[^a-z0-9_]*') AND (state IN ('queued', 'leased', 'sent_unknown', 'acknowledged', 'rejected', 'cancelled'))),
    lease_owner TEXT,
    lease_expires_at INTEGER,
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at INTEGER,
    last_error TEXT,
    result_watermark INTEGER,
    result TEXT,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (id)
) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_pending_commands__causal_order ON pending_commands (causal_order);
CREATE INDEX IF NOT EXISTS ix_pending_commands__state_next_attempt_at_created_at ON pending_commands (state, next_attempt_at, created_at);

-- command_dependencies <- projection-only
CREATE TABLE IF NOT EXISTS command_dependencies (
    command_id TEXT NOT NULL CHECK (length(command_id) = 36 AND command_id NOT GLOB '*[^0-9a-f-]*'),
    depends_on_command_id TEXT NOT NULL CHECK (length(depends_on_command_id) = 36 AND depends_on_command_id NOT GLOB '*[^0-9a-f-]*'),
    PRIMARY KEY (command_id, depends_on_command_id),
    CHECK (command_id <> depends_on_command_id),
    FOREIGN KEY (command_id) REFERENCES pending_commands (id) ON DELETE CASCADE,
    FOREIGN KEY (depends_on_command_id) REFERENCES pending_commands (id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

-- local_overlays <- projection-only
CREATE TABLE IF NOT EXISTS local_overlays (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    entity_type TEXT NOT NULL CHECK (length(entity_type) BETWEEN 1 AND 63 AND entity_type GLOB '[a-z]*' AND entity_type NOT GLOB '*[^a-z0-9_]*'),
    entity_key TEXT NOT NULL,
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('draft', 'command'))),
    command_id TEXT CHECK (command_id IS NULL OR (length(command_id) = 36 AND command_id NOT GLOB '*[^0-9a-f-]*')),
    reducer_version INTEGER NOT NULL,
    causal_order INTEGER NOT NULL,
    patch TEXT NOT NULL,
    base_version INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    CHECK ((kind = 'command') = (command_id IS NOT NULL)),
    FOREIGN KEY (command_id) REFERENCES pending_commands (id) ON DELETE CASCADE
) STRICT;
CREATE INDEX IF NOT EXISTS ix_local_overlays__entity_type_entity_key_causal_order ON local_overlays (entity_type, entity_key, causal_order);

-- upload_jobs <- projection-only
CREATE TABLE IF NOT EXISTS upload_jobs (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    command_id TEXT CHECK (command_id IS NULL OR (length(command_id) = 36 AND command_id NOT GLOB '*[^0-9a-f-]*')),
    local_path TEXT NOT NULL,
    sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
    byte_size INTEGER NOT NULL CHECK (byte_size >= 0),
    media_type TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'pending' CHECK ((length(state) BETWEEN 1 AND 63 AND state GLOB '[a-z]*' AND state NOT GLOB '*[^a-z0-9_]*') AND (state IN ('pending', 'uploading', 'uploaded', 'finalized', 'failed'))),
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at INTEGER,
    upload_url_expires_at INTEGER,
    last_error TEXT,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY (command_id) REFERENCES pending_commands (id) ON DELETE SET NULL
) STRICT;
CREATE INDEX IF NOT EXISTS ix_upload_jobs__state_command_id ON upload_jobs (state, command_id);

-- detail_cache <- projection-only
CREATE TABLE IF NOT EXISTS detail_cache (
    endpoint TEXT NOT NULL,
    entity_key TEXT NOT NULL,
    schema_version INTEGER NOT NULL,
    body TEXT NOT NULL,
    fetched_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    bytes INTEGER NOT NULL CHECK (bytes >= 0),
    PRIMARY KEY (endpoint, entity_key, schema_version)
) STRICT, WITHOUT ROWID;
